INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3361', 'spa', 'No; una negación subjetiva usada con modos no indicativos, en prohibiciones, prótasis condicionales y preguntas retóricas que esperan ''no''', 'La partícula negativa que expresa negación subjetiva, usada principalmente con modos no indicativos (subjuntivo, optativo, infinitivo, participio). Se emplea en prohibiciones (''no hagas''), en cláusulas condicionales, y en preguntas que anticipan una respuesta negativa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3362', 'spa', 'si acaso, si (partícula condicional con subjuntivo, de ἐάν contraída a κἄν con καί)', 'Esta partícula condicional introduce situaciones hipotéticas y suele ir seguida del modo subjuntivo. Las inscripciones áticas tempranas conservan la forma ἐάν, que se contrae en ἤν y ἄν en diversos dialectos. Cuando se combina con καί («y»), forma κἄν por crasis. En el griego helenístico y posterior, también funciona como ἄν tras pronombres relativos, creando construcciones como ὃς ἐάν («cualquiera que»). La partícula señala posibilidad y contingencia a lo largo del griego neotestamentario.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3363', 'spa', 'en aquel lugar, allí; donde; adonde (adverbio local, también conjunción final ''para que'')', 'Originalmente un adverbio local que significaba ''allí'' o ''en aquel lugar'', ἵνα evolucionó para significar también ''donde'' como relativo (''en el cual lugar''). Con verbos de movimiento puede significar ''adonde'' (hacia qué lugar). Combinado con ἄν y el subjuntivo (ἵν᾽ ἄν), expresa ''dondequiera que''. Más allá de sus usos espaciales, se desarrolló como una de las principales conjunciones de propósito y resultado del griego, aunque ese sentido final puede tratarse en otra entrada de este léxico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3364', 'spa', 'doble negación enfática: de ningún modo, en absoluto (en negación o prohibición)', 'La combinación οὐ μή constituye la negación más fuerte del griego, empleada para negar enfáticamente que algo sucederá o para prohibir una acción. En la negación categórica, aparece con mayor frecuencia con el aoristo de subjuntivo (''ciertamente no será atrapado por el engaño''). Ocasionalmente se usa el presente de subjuntivo con verbos de posibilidad o capacidad. Algunos estudiosos derivan ciertos usos de la elipsis de una expresión de temor o aprensión. La construcción transmite una negación absoluta con fuerza retórica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3366', 'spa', 'Ni, y no; como adverbio: ni siquiera -- partícula negativa que extiende o intensifica la negación.', 'Compuesto de μή y δέ, esta partícula funciona como la contrapartida subjuntiva/imperativa de οὐδέ, enlazando cláusulas negativas (''ni'') o intensificando una negación (''ni siquiera''). Jesús la emplea profusamente en el Sermón del Monte para acumular prohibiciones: «No os afanéis por vuestra vida... ni por vuestro cuerpo» (Mt 6:25), «No llevéis oro, ni plata, ni cobre» (Mt 10:9-10). En algunos pasajes aflora la fuerza adverbial: Mr 2:2 describe una multitud tan densa que «ni siquiera» el espacio junto a la puerta podía contenerlos. El español ''ni'' y ''ni siquiera'' reflejan ambos roles con precisión.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3367', 'spa', 'Nadie, ninguno; nada; ningún/a (adjetivo). Pronombre/adjetivo negativo para contextos no indicativos.', 'El compuesto griego μηδείς (de μηδέ + εἷς, literalmente ''ni siquiera uno'') es el pronombre y adjetivo negativo empleado con subjuntivo, imperativo, infinitivo y participio, la contrapartida no indicativa de οὐδείς. En los Evangelios aparece prominentemente en las órdenes de silencio de Jesús tras las sanaciones: «no lo digas a nadie» (Mt 8:4; 9:30; Mr 1:44). Como sustantivo neutro (μηδέν) significa ''nada'': «por nada estéis afanosos» (Fil 4:6), «nada hagáis por parcialidad» (1 Ti 5:21). Un uso adjetival más raro modifica sustantivos directamente: «ninguna ocasión de tropiezo» (1 Jn 2:10).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3368', 'spa', 'nunca, en ningún momento; negación enfática que abarca todo el tiempo', 'Este adverbio compuesto combina la partícula negativa con el marcador temporal indefinido para crear una negación temporal absoluta. En 2 Timoteo 3:7, Pablo describe a ciertas personas que siempre están aprendiendo pero nunca llegan al conocimiento de la verdad. La evidencia multilingüe es casi uniforme (nunca en español, jamais en francés), subrayando el alcance temporal absoluto. El uso clásico confirma que se trata de una negación fuerte que abarca todos los tiempos posibles, frecuente en prohibiciones o advertencias.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3369', 'spa', 'aún no, todavía no; negación de algo que no ha ocurrido hasta el momento presente', 'Este adverbio compuesto combina la negación con el marcador temporal de ''todavía'', creando una expresión que niega específicamente la culminación o llegada de algo hasta un punto de referencia dado. En Hebreos 11:7, describe el estado temporal del diluvio cuando Noé recibió la advertencia divina: acontecimientos aún no visibles cuando él actuó en fe. Las glosas multilingües (aún no en español, noch nicht en alemán) capturan uniformemente este matiz. Este preciso marcador temporal resalta la dimensión prospectiva de la fe.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3370', 'spa', 'Medos, pueblo antiguo de Media (actual noroeste de Irán)', 'Este sustantivo propio en plural designa a los habitantes de Media, el antiguo reino situado al sureste del mar Caspio. En Acts 2:9, los medos aparecen en el catálogo de pueblos presentes en Pentecostés que escucharon a los apóstoles hablar en sus lenguas nativas. Los medos fueron históricamente significativos como parte del imperio medo-persa y se mencionan con frecuencia en la profecía del Antiguo Testamento. Su presencia en Pentecostés representa la frontera oriental de la dispersión judía, ya que el territorio medo fue donde los israelitas del norte habían sido exiliados siglos antes.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3371', 'spa', 'Ya no, no más, nunca más — adverbio temporal negativo que indica el cese de un estado o acción previos', 'Ya no, no más, nunca más — adverbio temporal negativo que indica el cese de un estado o acción previos');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3372', 'spa', 'longitud, la dimensión lineal de un extremo a otro', 'La longitud es una de las dimensiones espaciales fundamentales. Pablo ora para que los creyentes comprendan las dimensiones plenas del amor de Cristo: anchura, longitud, altura y profundidad (Ef 3:18). En la visión de Juan sobre la Nueva Jerusalén, la ciudad es medida y su longitud es igual a su anchura y su altura, formando un cubo perfecto (Ap 21:16, mencionado dos veces). El término es directo: extensión lineal. El griego μῆκος es un vocablo geométrico estándar sin complejidad metafórica en estos pasajes.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3373', 'spa', 'crecer, alargarse, aumentar en longitud o duración', 'Este verbo significa principalmente hacer o hacerse largo, extenderse en el espacio o en el tiempo. En Mark 4:27, Jesús lo emplea en su parábola de la semilla que crece para describir el proceso misterioso del crecimiento: la semilla brota y crece mientras el sembrador duerme, sin saber cómo sucede. Las glosas multilingües enfatizan consistentemente el crecimiento (español crezca, francés grandir, alemán lang werden). El uso clásico incluye alargar el tiempo, prolongar un discurso o la extensión física, siendo la metáfora agrícola particularmente vívida en el contexto de Marcos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3374', 'spa', 'piel de oveja, vestimenta o cobertura hecha de lana o cuero de oveja', 'Este sustantivo femenino designa una prenda tosca hecha de lana o cuero de oveja, típicamente usada por profetas, ascetas o personas indigentes. En Hebrews 11:37, aparece en el catálogo de sufrimientos soportados por los testigos fieles que anduvieron cubiertos con pieles de oveja y de cabra. Tales vestiduras rústicas simbolizaban tanto la pobreza voluntaria como la marginación social, señalando a quienes las portaban como personas al margen de la sociedad convencional. La imagen evoca el tosco manto de Elías y la tradición profética veterotestamentaria.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3375', 'spa', 'ciertamente, de veras; partícula enfática que refuerza una aseveración o afirmación solemne', 'Esta partícula intensiva sirve para reforzar juramentos, promesas y declaraciones solemnes. En Hebrews 6:14, aparece en la cita del juramento de Dios a Abraham, subrayando la certeza absoluta de la promesa divina. Las glosas multilingües expresan consistentemente una afirmación enérgica (español ciertamente, francés/alemán gewiss). El uso clásico muestra esta partícula colocada después de la palabra enfatizada para añadir solemnidad y certidumbre a la declaración, particularmente en juramentos y promesas. El contexto destaca la naturaleza inquebrantable de la palabra de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3376', 'spa', 'Μήν (genitivo μηνός) es la palabra griega estándar para ''mes,'' y aparece 18 veces en el Nuevo Testamento en contextos narrativos, proféticos y apocalí', 'Μήν (genitivo μηνός) es la palabra griega estándar para ''mes,'' y aparece 18 veces en el Nuevo Testamento en contextos narrativos, proféticos y apocalípticos. La narración lucana de la infancia es rica en meses: Elisabet se recluye durante ''cinco meses'' (Lc 1:24), el ángel visita a María en ''el sexto mes'' del embarazo de Elisabet (Lc 1:26, 36), y María permanece con Elisabet ''unos tres meses'' (Lc 1:56). Santiago invoca la oración de Elías que cerró los cielos por ''tres años y seis meses'' (Stg 5:17; cf. Lc 4:25). Hechos registra que Pablo enseñó en Corinto durante ''dieciocho meses'' (Hch 18:11) y en Éfeso ''tres meses'' en la sinagoga (Hch 19:8; 20:3). En Apocalipsis, los meses se convierten en medidas proféticas: a la bestia se le otorga autoridad por ''cuarenta y dos meses'' (Ap 9:5, 10, 15; 11:2; 13:5), en eco del período de tribulación de tres años y medio de Daniel. El árbol de la vida da fruto ''cada mes'' (Ap 22:2).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3377', 'spa', 'Revelar, informar o dar a conocer lo que estaba oculto o era desconocido.', 'Este verbo significa revelar, informar o dar aviso, con el matiz particular de divulgar algo previamente desconocido o sacar a la luz información oculta. Sus usos neotestamentarios abarcan desde la revelación indirecta de Jesús de que Dios es Dios de vivos (Lc 20:37, «Moisés indicó»), hasta las autoridades religiosas buscando a alguien que informara del paradero de Jesús (Jn 11:57), pasando por el informe urgente de un sobrino sobre un complot de asesinato (Hch 23:30), y alguien que avisa a un creyente sobre el origen idolátrico de comida ofrecida en una cena (1 Co 10:28). Las diversas traducciones — francés «dénoncer», alemán «mitteilen» — iluminan distintas facetas del acto de revelar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3378', 'spa', 'negación tras temor o aprensión: que no, no sea que no (μὴ οὐ con subjuntivo o indicativo)', 'Esta construcción de doble negación sigue a verbos que expresan temor o aprensión, introduciendo un resultado negativo que se teme. Homero la emplea: ''temo que nadie emprenda esta obra por ti'' (es decir, ''temo que nadie lo hará''). Aparece con mayor frecuencia con el subjuntivo, aunque también se documenta con el indicativo. A veces introduce una vacilación sin un verbo introductorio explícito. La construcción capta la complejidad psicológica de temer algo negativo: ''temer que... no''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3379', 'spa', 'no sea que, para que no; expresa propósito negativo o temor aprensivo', 'Esta conjunción compuesta introduce una cláusula que expresa una consecuencia temida o un propósito negativo. En Matthew 25:9, las vírgenes prudentes la emplean para explicar por qué no pueden compartir su aceite: no sea que no alcance para ambos grupos. La evidencia multilingüe muestra variación interpretativa: español quizás, francés de peur que (por temor de que). El uso clásico abarca prohibiciones, advertencias y cláusulas de propósito que expresan lo que debe evitarse. El término porta matices tanto de precaución como condicionales, combinando el cálculo prudente con la aprensión genuina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3381', 'spa', 'todavía no (adverbio); no sea que aún (conjunción con subjuntivo)', 'Como adverbio, μήπω significa ''todavía no'', a menudo con énfasis: ''no, aún no''. Homero lo emplea tanto en la narración como en el diálogo. Como conjunción, introduce una cláusula preventiva: ''no sea que aún alguien pase desapercibido''. La palabra combina la negación μή con πω, la partícula temporal que indica ''aún'' o ''hasta ahora''. Expresa un estado incompleto o una ocurrencia prematura que se teme.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3382', 'spa', 'muslo, parte superior de la pierna desde la cadera hasta la rodilla', 'Este sustantivo masculino designa la parte superior de la pierna, particularmente prominente en contextos antiguos relacionados con la guerra, los juramentos y el simbolismo real. En Apocalipsis 19:16, Juan ve un nombre escrito en el muslo del jinete conquistador sobre el caballo blanco: Rey de Reyes y Señor de Señores. La práctica antigua incluía portar insignias reales en el muslo, y los guerreros llevaban espadas sujetas allí, convirtiéndolo en un lugar asociado con el poder y la autoridad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3383', 'spa', 'Ni, tampoco; conjuncion negativa usada en pares (μήτε...μήτε) para negar dos o mas alternativas.', 'Ni, tampoco; conjuncion negativa usada en pares (μήτε...μήτε) para negar dos o mas alternativas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3384', 'spa', 'Madre; mujer en su rol de progenitora, también usado figuradamente de ciudades, pactos y relaciones espirituales.', 'El término griego estándar para ''madre'', empleado abrumadoramente en el sentido literal de la relación parental biológica o social. María es identificada como la madre de Jesús a lo largo de los relatos de la infancia (Mt 1:18; 2:11, 13-14), y el vocablo estructura el discurso familiar en los Evangelios y las Epístolas. La expresión «desde el vientre de su madre» (Hch 3:2; 14:8; Gá 1:15) funciona como modismo que significa ''desde el nacimiento'', revelando una construcción preposicional secundaria. Todas las lenguas de destino traducen uniformemente --español ''madre'', francés ''mère'', alemán ''Mutter''--, lo que confirma la estabilidad semántica de este término de parentesco fundamental.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3385', 'spa', 'Μήτι es una partícula interrogativa que formula una pregunta esperando la respuesta ''no.'' Introduce preguntas retóricas en las que el hablante anticip', 'Μήτι es una partícula interrogativa que formula una pregunta esperando la respuesta ''no.'' Introduce preguntas retóricas en las que el hablante anticipa una negación o expresa incredulidad. Cuando las multitudes preguntan ''¿Acaso no será este el Hijo de David?'' (Mt 12:23), la partícula señala su vacilación. En la Última Cena, cada discípulo pregunta ''¿Acaso soy yo?'' (Mt 26:22, 25). En Juan 4:29, la pregunta de la mujer samaritana — ''¿No será este el Cristo?'' — usa μήτι para expresar una incertidumbre esperanzada mientras formalmente espera una negación. El español ''acaso'' y el alemán ''etwa'' capturan este matiz interrogativo cargado de duda.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3386', 'spa', 'cuánto más, usado en argumentos a fortiori que avanzan de lo menor a lo mayor', 'Esta frase adverbial funciona en el razonamiento comparativo, estableciendo un argumento que va del caso menor al mayor. En 1 Corintios 6:3, Pablo la emplea para razonar que si los creyentes juzgarán a los ángeles, cuánto más los asuntos de la vida ordinaria. Este recurso retórico aparece frecuentemente en la argumentación rabínica y a lo largo de las Escrituras, extrayendo conclusiones inevitables a partir de premisas aceptadas. Su fuerza lógica radica en hacer irrefutable la conclusión mayor.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3387', 'spa', 'alguien, algo (indefinido, = μηδείς en griego antiguo/cretense); en preguntas, imperativos, deseos, tras temor/duda', 'Forma del griego antiguo y cretense equivalente a μηδείς (''nadie''), este pronombre indefinido aparece en Homero y en inscripciones cretenses. Como adverbio (μή τι), acompaña imperativos y deseos en optativo. Tras verbos de temor o duda, introduce cláusulas aprensivas. En preguntas directas, μή τί σοι δοκῶ significa ''¿acaso te parezco...?'' (esperando ''no''). La expresión μή τί γε significa ''y mucho menos'' o ''ni qué decir'', expresando una negación fuerte: ''ni siquiera digno de ser soldado, mucho menos comandante de otros''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3389', 'spa', 'quien golpea o asesina a su madre; matricida', 'Este sustantivo compuesto designa a quien comete violencia contra su madre, particularmente hasta el punto del asesinato. En 1 Timoteo 1:9-10, aparece en el catálogo paulino de conductas inicuas para las cuales fue establecida la ley. Los códigos morales antiguos condenaban universalmente tales violaciones del orden familiar como representación del quiebre total del afecto natural y la estructura social. El término aparece junto a los parricidas, enfatizando las transgresiones del quinto mandamiento.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3390', 'spa', 'ciudad madre, metrópoli (ciudad en relación con sus colonias); fuente u origen de algo', 'Una μητρόπολις es una ''ciudad madre'' en relación con las colonias que fundó: Atenas respecto a los jonios, Corinto respecto a Corcira, Tera respecto a las grandes ciudades que nacieron de ella. El término expresa la relación colonial en la que una ciudad engendra otra y conserva un estatus parental. En sentido figurado, puede significar ''fuente'' u ''origen'', como cuando se llama al cerebro la ''metrópoli del frío'' o a la geometría el ''principio y ciudad madre'' de las demás ciencias. Con el tiempo, pasó a designar cualquier ciudad principal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3391', 'spa', 'uno (numeral y enfático); uno solo, único; εἷς con femenino μία y neutro ἕν', 'El numeral ''uno'' funciona tanto como cifra simple como con valor enfático: ''que haya un solo gobernante'', declara Homero. Formas reforzadas como εἷς οἶος significan ''uno solo, sin nadie más''. La palabra puede subrayar unicidad, unidad o singularidad. Sus formas oblicuas (genitivo ἑνός, dativo ἑνί) provienen de una raíz indoeuropea emparentada con el latín ''sem-'' (como en ''simple''). El femenino μία procede de un tema distinto al del masculino y neutro, conservando una complejidad morfológica muy antigua.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3392', 'spa', 'Contaminar, manchar o hacer impuro en sentido ceremonial, moral o espiritual; corromper o profanar.', 'Evoca tanto la contaminación ritual como la moral. Los líderes judíos se negaron a entrar en el pretorio para no contaminarse antes de la Pascua (Jn 18:28), lo que ilustra su fuerza ceremonial. Pero Pablo transforma el concepto: para los puros todo es puro, mas para los contaminados nada es puro (Tit 1:15). Hebreos advierte contra cualquier raíz de amargura que pueda contaminar a muchos (Heb 12:15), y Judas condena a quienes contaminan la carne (Jud 1:8). El término abarca desde la impureza ritual hasta la corrupción moral profunda.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3393', 'spa', 'contaminación, polución; aquello que contamina moral o ceremonialmente', 'Este sustantivo neutro denota mancha, polución o contaminación, particularmente en contextos de corrupción moral o religiosa. En 2 Pedro 2:20, describe las contaminaciones del mundo de las cuales las personas escapan mediante el conocimiento de Cristo. El uso clásico incluye la polución derivada del asesinato o el crimen, la mancha de la culpa, y de manera más general cualquier influencia contaminante. El término abarca tanto el sentido de agente contaminante como el estado resultante de impureza.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3394', 'spa', 'impureza, el acto o estado de estar contaminado o poluto', 'Este sustantivo masculino es paralelo cercano de G3393, denotando el acto o estado de contaminación y polución moral. En 2 Pedro 2:10, caracteriza a quienes andan según la carne en la concupiscencia de impureza. Aunque casi sinónimo de μίασμα, este término puede enfatizar más el proceso o estado de la contaminación que el agente contaminante en sí. Ambas palabras pertenecen al campo semántico de la contaminación cúltica y moral prevalente en el discurso religioso helenístico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3395', 'spa', 'una mezcla, un compuesto que combina varios ingredientes', 'Este sustantivo neutro designa una mezcla o compuesto, generalmente de sustancias combinadas entre sí. En Juan 19:39, describe la preparación que Nicodemo trajo para la sepultura de Jesús: una mezcla de mirra y áloes que pesaba alrededor de setenta y cinco libras. Las traducciones multilingües identifican de manera uniforme la idea de mezcla o compuesto. En el uso clásico, el término abarca drogas mezcladas, pigmentos, condimentos o amalgamas. El vocablo enfatiza la naturaleza combinada de la preparación más que sus componentes individuales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3396', 'spa', 'Mezclar o combinar una sustancia con otra; unir líquidos o materiales entre sí.', 'Verbo básico que designa la acción física de mezclar o combinar sustancias. Sus apariciones en el Nuevo Testamento son vívidas y memorables: el vino mezclado con hiel ofrecido a Jesús en la cruz (Mt 27:34), Pilato que mezcló la sangre de unos galileos con la de sus sacrificios (Lc 13:1), fuego mezclado con sangre cayendo del cielo (Ap 8:7) y un mar de vidrio mezclado con fuego ante el trono de Dios (Ap 15:2). Todas las traducciones reflejan de modo consistente la idea de combinar elementos dispares en uno solo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3397', 'spa', 'pequeño, poco (en tamaño, estatura, edad o importancia); σμικρός/μικρός con variantes dialectales', 'Este adjetivo significa ''pequeño'' o ''poco'' y abarca el tamaño físico (''pequeño de estatura''), la juventud y la insignificancia; incluso puede usarse como reproche. La comedia lo emplea con exageración hiperbólica: ''un tribunalito muy pequeñito''. La expresión ''pequeño de ver'' equivale a ''difícil de percibir''. Se opone a μέγας en toda la literatura griega. La alternancia dialectal entre σμικρός y μικρός refleja diferencias regionales de pronunciación; las inscripciones áticas conservan la sigma inicial. Se aplica literalmente a objetos físicos y metafóricamente a la posición social.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3398', 'spa', 'Pequeno, poco; como adverbio ''un poco de tiempo''; sustantivado como ''los pequenos'', los humildes o insignificantes', 'Pequeno, poco; como adverbio ''un poco de tiempo''; sustantivado como ''los pequenos'', los humildes o insignificantes');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3399', 'spa', 'Mileto, antigua ciudad griega portuaria en la costa occidental de Asia Menor', 'Mileto fue una importante ciudad portuaria en Caria, sobre la costa egea de la actual Turquía. Pablo se detuvo allí en su último viaje a Jerusalén y convocó a los ancianos de Éfeso para una emotiva despedida (Hechos 20:15, 17). Más adelante, dejó enfermo allí a Trófimo (2 Timoteo 4:20). La ciudad tenía una rica historia como centro de filosofía y comercio griego. El nombre se mantiene transliterado de forma consistente en todas las lenguas, reflejando su condición de nombre propio geográfico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3400', 'spa', 'una milla romana, unidad de distancia equivalente a unos 1.000 pasos o 1.480 metros', 'Este sustantivo neutro representa la milla romana (mille passus), una unidad de distancia estándar en el mundo antiguo. En Mateo 5:41, Jesús la emplea en su enseñanza sobre ir más allá de lo que la ley exige: si alguien te obliga a caminar una milla, ve dos. Las traducciones multilingües identifican de manera consistente la milla como medida de distancia. La milla romana era ligeramente más corta que la milla moderna, midiendo aproximadamente 1.480 metros. La enseñanza de Jesús presupone el trabajo forzado que los soldados romanos podían imponer legalmente a los civiles.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3401', 'spa', 'Imitar, seguir como modelo; reproducir en la propia conducta el ejemplo de otro.', 'Verbo en voz media que exhorta a los creyentes a reproducir en su vida la conducta observada en líderes piadosos. En 2 Tesalonicenses 3:7-9, Pablo ofrece su propio trabajo como modelo a seguir, mientras que Hebreos 13:7 amplía el llamado a imitar la fe de los pastores que ya partieron. El contrapunto negativo en 3 Juan 1:11 advierte contra imitar lo malo, mostrando que el verbo no tiene una dirección moral inherente: es el modelo escogido lo que determina el resultado. El sentido es el de una réplica conductual deliberada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3402', 'spa', 'Imitador; quien sigue el ejemplo o modelo de otro, especialmente en fe y conducta.', 'Mimetes llama a los creyentes a emular activamente modelos dignos de imitación. Pablo exhorta con audacia a los corintios: «Sed imitadores de mí» (1 Corintios 4:16), y luego precisa la cadena: «Sed imitadores de mí, así como yo de Cristo» (1 Corintios 11:1). El concepto se eleva hasta Dios mismo en Efesios 5:1, donde se invita a los creyentes a imitarlo como hijos amados. Los tesalonicenses llegaron a ser imitadores tanto de los apóstoles como del Señor al recibir la palabra con gozo en medio del sufrimiento (1 Tesalonicenses 1:6), y de las iglesias de Judea al soportar la persecución (1 Tesalonicenses 2:14). La palabra conlleva la fuerza de un modelado intencional y devoto de la propia vida.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3403', 'spa', 'Recordar o traer a la memoria; evocar activamente personas, eventos o verdades, o ser traído al recuerdo de forma pasiva', 'Recordar o traer a la memoria; evocar activamente personas, eventos o verdades, o ser traído al recuerdo de forma pasiva');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3404', 'spa', 'Odiar, aborrecer; sentir profunda hostilidad, o en modismo semitico, amar menos en comparacion', 'Odiar, aborrecer; sentir profunda hostilidad, o en modismo semitico, amar menos en comparacion');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3405', 'spa', 'Recompensa, retribución; el pago o consecuencia merecidos por las acciones realizadas', 'Este término designa la recompensa o retribución que sigue a una acción, ya sea positiva o negativa. Hebreos advierte que las transgresiones bajo el Antiguo Pacto recibieron una «justa retribución» (Heb 2:2). El mismo libro alienta a mantener la confianza en la promesa de Dios, que trae «gran recompensa» (Heb 10:35). Moisés perseveró mirando hacia la «recompensa» venidera en lugar de los tesoros de Egipto (Heb 11:26). La palabra abarca tanto la consecuencia judicial como el galardón misericordioso.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3406', 'spa', 'el que paga salario o da recompensa; un remunerador, galardoneador', 'Este sustantivo masculino compuesto designa a quien distribuye pago, salario o recompensa. En Hebreos 11:6, describe a Dios como el galardonador de quienes le buscan con diligencia. Las traducciones multilingües identifican uniformemente al remunerador o quien recompensa. El término combina la raíz de salario (μισθός) con un sufijo de agente, creando la imagen de Dios como aquel que fielmente retribuye a quienes buscan con empeño una relación con Él. No se trata de mérito humano, sino de la generosidad divina hacia quienes le buscan de corazón.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3407', 'spa', 'Jornalero, trabajador asalariado que labora a cambio de un salario', 'Se refiere a los trabajadores asalariados, empleados que no son ni esclavos ni miembros de la familia. En la parábola de Jesús, el hijo pródigo se da cuenta de que incluso los «jornaleros» de su padre tienen comida de sobra (Lucas 15:17) y decide pedir que lo acepten como tal (Lucas 15:19, 21). El término señala un estatus social: no es hijo ni esclavo, sino un trabajador a sueldo. Esta posición intermedia se convierte en el punto de reingreso que el pródigo anhela.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3408', 'spa', 'Salario, recompensa, galardón — pago ganado por el trabajo o retribución divina por la conducta', 'Salario, recompensa, galardón — pago ganado por el trabajo o retribución divina por la conducta');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3410', 'spa', 'vivienda alquilada, alojamiento obtenido mediante pago; casa rentada', 'Este sustantivo neutro denota algo alquilado o arrendado, particularmente un espacio habitacional obtenido mediante pago. En Hechos 28:30, describe la situación de vivienda de Pablo en Roma: permaneció dos años enteros en su propia casa alquilada. Las traducciones multilingües identifican una casa o vivienda rentada. En el uso clásico, el término abarca precio de contrato, pagos de renta o propiedad arrendada. La precisión de Lucas enfatiza que Pablo, aunque bajo arresto domiciliario, costeaba su propio alojamiento, lo cual le permitía recibir a todos los que acudían a él.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3411', 'spa', 'Asalariado, jornalero; quien trabaja por paga y no por lealtad ni sentido de pertenencia', 'Un asalariado es alguien que trabaja a cambio de un salario y no por sentido de pertenencia ni devoción. Marcos registra que Jacobo y Juan dejaron a su padre «con los jornaleros» (Marcos 1:20). Jesús contrasta al buen pastor, dueño de las ovejas, con el asalariado que huye ante el peligro porque «es asalariado y no le importan las ovejas» (Juan 10:12-13). El término implica una motivación mercenaria: presente mientras haya paga, ausente cuando el costo sea alto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3412', 'spa', 'Mitilene, la ciudad principal de la isla de Lesbos en el mar Egeo', 'Este nombre propio designa la ciudad principal de Lesbos, un importante puerto en el viaje de Pablo hacia Jerusalén. En Hechos 20:14, Lucas registra la llegada a Mitilene como parte del viaje de isla en isla desde Troas. La evidencia multilingüe simplemente transliterara el topónimo. Mitilene era un centro cultural y comercial significativo en el Egeo antiguo, conocido por sus poetas y su puerto estratégico. La escala allí encaja en el patrón típico de navegación costera del Mediterráneo antiguo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3414', 'spa', 'Mina; antigua unidad de peso y moneda equivalente a unas 100 dracmas, usada en la parabola de Jesus sobre las minas.', 'Prestamo semitico (hebreo maneh) que designa una unidad de peso y valor monetario equivalente a aproximadamente 100 dracmas o unos cuatro meses de salario de un jornalero. En el NT aparece unicamente en la Parabola de las Minas (Lc 19:11-27), donde un hombre noble reparte diez minas entre diez siervos antes de partir. A diferencia de los ''talentos'' mayores de Mateo 25, la mina es una suma mas modesta, lo que hace aun mas elocuente la fidelidad de los siervos con cantidades pequenas. El espanol ''mina'' y el frances ''mine'' conservan el termino semitico sin cambios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3415', 'spa', 'recordar, tener presente (con genitivo); cortejar, pretender a una novia', 'Este verbo significa principalmente ''recordar'' o ''tener presente'', y rige genitivo: ''no se acordaban de la guerra'', ''cuando lo recuerdo''. También puede significar ''dirigir la mente hacia'' algo. Un segundo sentido, ausente en Homero pero frecuente después, es ''cortejar'' o ''pretender a una novia''. El verbo abarca tanto la atención mental —recordar, ser consciente— como la búsqueda amorosa. La conexión entre memoria y cortejo refleja el carácter activo e intencional de ambas acciones.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3416', 'spa', 'Mnasón, discípulo chipriota que brindó hospitalidad a Pablo en Jerusalén', 'Este sustantivo propio masculino identifica a un creyente específico de la iglesia primitiva que hospedó a la comitiva de Pablo. En Hechos 21:16, Lucas describe a Mnasón como un discípulo antiguo, originario de Chipre, en cuya casa se alojaría el grupo de Pablo al llegar a Jerusalén. La expresión «discípulo antiguo» sugiere que Mnasón fue uno de los primeros convertidos, posiblemente en Pentecostés o poco después. Su origen chipriota lo vincula con la patria de Bernabé, reforzando las conexiones entre la comunidad cristiana temprana y la diáspora judía.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3417', 'spa', 'Recuerdo, mención; el acto de traer a alguien a la memoria, especialmente en oración; evocación piadosa de una persona o comunidad.', 'μνεία designa el acto de traer a alguien o algo a la mente, y en el NT aparece casi exclusivamente en la frase ''haciendo mención de vosotros en mis oraciones''. Pablo la emplea como sello de su calidez pastoral, asegurando a los romanos (1:9), efesios (1:16), filipenses (1:3) y tesalonicenses (1 Ts 1:2; 3:6) que viven en su memoria orante. La palabra tiende un puente entre el recuerdo y la palabra: hacer μνεία es a la vez recordar y nombrar a alguien delante de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3418', 'spa', 'Tumba, sepulcro o monumento funerario; lugar preparado para enterrar a los muertos, especialmente una cámara excavada en roca.', 'Mnema proviene de la raíz de memoria (μνάομαι, recordar): una tumba es, en su esencia etimológica, un memorial. En el griego clásico, la palabra podía referirse a cualquier monumento o recuerdo, pero en el Nuevo Testamento se restringe a lugares de sepultura: el endemoniado gadareno que habitaba entre los sepulcros (Marcos 5:3, 5:5), la tumba recién labrada donde fue puesto Jesús (Lucas 23:53) y el sepulcro de David aún presente en Jerusalén (Hechos 2:29). El vínculo etimológico con la memoria subyace al sentido original de la palabra como memorial del difunto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3419', 'spa', 'Tumba, sepulcro, monumento funerario o memorial de los muertos', 'Tumba, sepulcro, monumento funerario o memorial de los muertos');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3420', 'spa', 'memoria, recuerdo; la facultad o el acto de evocar algo pasado', 'Este sustantivo femenino designa la memoria, el recuerdo o la facultad mental de evocar acontecimientos pasados. En 2 Pedro 1:15, Pedro expresa su intención de asegurar que sus lectores puedan recordar estas verdades después de su partida. El uso clásico distingue esta facultad natural de memoria de la ἀνάμνησις (evocación deliberada). El término puede referirse tanto a la capacidad de recordar como al contenido mismo de lo recordado, abarcando así el acto y el objeto del recuerdo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3421', 'spa', 'Recordar, traer a la memoria, tener presente; evocar eventos pasados, palabras o personas en la conciencia activa', 'Recordar, traer a la memoria, tener presente; evocar eventos pasados, palabras o personas en la conciencia activa');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3422', 'spa', 'Memorial, recordatorio; aquello que preserva la memoria de alguien o algo', 'Un memorial es algo que se hace u ofrece para preservar la memoria. Jesús dice que la unción de la mujer será contada «para memoria de ella» dondequiera que se predique el evangelio (Mateo 26:13, Marcos 14:9). Las oraciones y limosnas de Cornelio subieron «como memorial delante de Dios» (Hechos 10:4), es decir, Dios las recuerda. El término enfatiza la preservación del recuerdo mediante una acción o una ofrenda, ya sea en la memoria humana o ante la atención divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3423', 'spa', 'desposada, prometida en matrimonio mediante un compromiso legalmente vinculante', 'En la cultura judía, el desposorio era mucho más vinculante que el compromiso moderno: constituía un acuerdo legal que solo podía disolverse mediante divorcio. María estaba «desposada» con José cuando fue hallada encinta (Mt 1:18) y es llamada «una virgen desposada con un hombre llamado José» (Lc 1:27). Viajó a Belén «con María, su desposada» (Lc 2:5). Esta condición era jurídicamente equivalente al matrimonio, aunque aún no se había consumado. Las tres apariciones en el NT describen exclusivamente el estado nupcial de María.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3424', 'spa', 'que habla con dificultad, con impedimento del habla; tartamudo o que articula con esfuerzo', 'Este adjetivo compuesto describe a alguien con habla impedida o dificultad para articular con claridad. En Marcos 7:32, traen ante Jesús a un hombre sordo y con impedimento del habla, pidiendo sanación. El término combina las ideas de «con dificultad» y «hablar», retratando una articulación laboriosa o deficiente. En el mundo antiguo, esta condición se asociaba frecuentemente con la sordera, ya que la incapacidad de oír impedía la formación correcta de las palabras. La sanación de Jesús demuestra su poder sobre las discapacidades físicas y cumple la profecía de Isaías.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3425', 'spa', 'apenas, difícilmente, con dificultad; a duras penas', 'Este adverbio expresa la idea de algo logrado con dificultad, esfuerzo o por un margen muy estrecho. En Lucas 9:39, describe la salida renuente del demonio del niño afligido: lo sacude violentamente y apenas lo deja, dejándolo magullado en el proceso. El uso clásico transmite consistentemente la noción de trabajo arduo, penalidad o estrechez en la consecución de algo. La palabra enfatiza que la acción se realiza, pero solo a costa de un gran esfuerzo o resistencia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3426', 'spa', 'almud, cajón o recipiente de medida para grano seco', 'El modio era una medida romana para áridos, equivalente aproximadamente a un almud o celemín. Jesús lo emplea como objeto doméstico en su enseñanza sobre la luz: nadie enciende una lámpara para ponerla «debajo de un almud» (Mt 5:15; Mr 4:21; Lc 11:33). La imagen resulta absurda: ocultar la luz bajo un recipiente de grano. El punto es la visibilidad y el propósito de la luz. El término griego μόδιος proviene del latín modius, una medida estándar de unos 8,75 litros.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3427', 'spa', 'yo, pronombre de primera persona (formas enfáticas/especiales; entrada variante de G3165)', 'Esta entrada duplica G3165 y recoge formas adicionales o apariciones textuales del pronombre de primera persona ἐγώ. La forma reforzada ἔγωγε (''yo por lo menos'', ''por mi parte'') aparece con más frecuencia en el ático que en Homero. Entre las variantes dialectales se encuentran el dórico ἐγώνγα y el beocio ἱώνγα. Los casos oblicuos proceden de una raíz distinta: genitivo ἐμοῦ (enclítico μου), y las formas jónica y épica conservan variantes más antiguas como ἐμέο y ἐμέθεν.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3428', 'spa', 'Adúltera; en sentido figurado, espiritualmente infiel a Dios — adúltero/a (referido a una generación)', 'El sustantivo μοιχαλίς (''adúltera'') porta un doble significado en el Nuevo Testamento, tanto literal como metafórico. En su uso figurado —que es el más frecuente— Jesús denuncia a ''una generación adúltera y pecadora'' (Mt 12:39; 16:4; Mr 8:38), recogiendo la profunda tradición profética de Oseas, Jeremías y Ezequiel, donde la infidelidad de Israel hacia Dios se representa como traición conyugal. Santiago hace eco de esto al dirigirse a los creyentes descarriados como ''adúlteras'' (Stg 4:4), calificando la amistad con el mundo como infidelidad espiritual. El sentido literal aparece en la analogía matrimonial de Pablo en Romanos 7:3, donde la mujer que toma otro esposo en vida del suyo ''será llamada adúltera''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3429', 'spa', 'Cometer adulterio; se aplica tanto a hombres como a mujeres que quebrantan el pacto matrimonial por infidelidad sexual.', 'Forma estrechamente emparentada con μοιχεύω que aparece en la enseñanza de Jesús sobre el divorcio y las segundas nupcias. En el Sermón del Monte y en el diálogo posterior sobre el divorcio, Jesús declara que quien se divorcia y se vuelve a casar comete adulterio, aplicando esto tanto a maridos (Mt 5:32; 19:9; Mr 10:11) como a esposas (Mr 10:12). El término conlleva un peso moral inequívoco: nombra la violación del pacto matrimonial. Las traducciones convergen de manera uniforme en la expresión directa «cometer adulterio».');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3430', 'spa', 'adulterio, infidelidad sexual dentro del matrimonio', 'El adulterio es la traición sexual dentro del vínculo matrimonial, una violación del séptimo mandamiento. Jesús lo incluye entre los males que contaminan desde el interior del corazón (Mt 15:19; Mr 7:21). Juan 8:3 relata el caso de una mujer «sorprendida en adulterio». El término aparece tanto en singular (el acto concreto) como en plural (la práctica reiterada). Constituye una transgresión moral paradigmática en la ética bíblica, pues quebranta la fidelidad pactada en el matrimonio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3431', 'spa', 'Cometer adulterio; en sentido causativo, provocar o hacer que ocurra el adulterio. Uno de los términos morales más graves del Nuevo Testamento, μοιχεύ', 'Cometer adulterio; en sentido causativo, provocar o hacer que ocurra el adulterio. Uno de los términos morales más graves del Nuevo Testamento, μοιχεύω aparece en la intensificación que Jesús hace de la prohibición de la Torá: no solo el acto físico, sino incluso la mirada lujuriosa constituye adulterio del corazón (Mt 5:27-28). La palabra reaparece en los Evangelios Sinópticos en el contexto del séptimo mandamiento del Decálogo. La enseñanza de Jesús sobre el divorcio (Mt 5:32) introduce una dimensión causativa: quien repudia injustamente a su cónyuge ''hace que ella adultere.''');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3432', 'spa', 'adúltero, quien comete infidelidad sexual en el matrimonio', 'Un adúltero es quien comete infidelidad sexual dentro del matrimonio. El fariseo de la parábola de Jesús da gracias a Dios por no ser como los «adúlteros» (Lc 18:11). Pablo advierte que los adúlteros no heredarán el reino de Dios (1 Co 6:9). Hebreos declara que «Dios juzgará a los adúlteros» (Heb 13:4). Aunque el término griego μοιχός es gramaticalmente masculino, funciona como categoría general que abarca a quienes violan la fidelidad conyugal, sin distinción de sexo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3433', 'spa', 'Apenas, con dificultad, a duras penas; indica que una acción se logra solo con gran esfuerzo o por escaso margen.', 'Molis transmite la idea de que algo ocurre apenas o con gran dificultad. Lucas favorece este adverbio, empleándolo cuatro veces en Hechos para describir situaciones donde el desenlace pendía de un hilo: los apóstoles apenas lograron disuadir a la multitud de ofrecerles sacrificios (Hch 14:18), la nave avanzaba con dificultad a lo largo de la costa de Creta (Hch 27:7-8) y los marineros a duras penas pudieron asegurar el esquife durante la tormenta (Hch 27:16). Pablo lo usa teológicamente en Romanos 5:7, señalando que apenas alguien moriría aun por un justo, realzando por contraste la maravilla de la muerte de Cristo por los pecadores.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3434', 'spa', 'Moloc, deidad amonita a la que se sacrificaban niños', 'Este sustantivo propio indeclinable designa a la deidad pagana adorada por los amonitas, asociada con el sacrificio de niños. En Hechos 7:43, Esteban cita Amós 5:26 para condenar la apostasía de Israel al cargar con la imagen de Moloc durante el período del desierto. El nombre es una vocalización deliberada que sustituye las vocales de «rey» (mélek) por las de la palabra hebrea para «vergüenza» (bóshet). El culto a Moloc representó una de las corrupciones idolátricas más graves de Israel, un símbolo de la traición espiritual más profunda.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3435', 'spa', 'contaminar, manchar, hacer ritual o moralmente impuro', 'Contaminar significa hacer impuro, ya sea en sentido ritual o moral. Pablo habla de aquellos cuya conciencia débil «se contamina» al comer alimentos ofrecidos a ídolos (1 Co 8:7). Jesús elogia a los pocos en Sardis que «no han manchado sus vestiduras» (Ap 3:4). Los 144.000 son quienes «no se contaminaron con mujeres» (Ap 14:4). El término griego μολύνω abarca tanto la contaminación ceremonial como la corrupción moral, evocando la imagen de una mancha que ensucia lo que antes estaba limpio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3436', 'spa', 'contaminación, polución; impureza moral o espiritual que mancha tanto el cuerpo como el espíritu', 'Este sustantivo masculino designa la polución o contaminación moral y ceremonial. En 2 Corintios 7:1, Pablo exhorta a los creyentes a purificarse de toda contaminación de carne y espíritu. El término pertenece al vocabulario de pureza, central tanto en el pensamiento cúltico judío como en la ética cristiana primitiva, donde la pureza moral y espiritual reemplazó las regulaciones ceremoniales sin abandonar los conceptos subyacentes de contaminación y limpieza. Las traducciones multilingües identifican uniformemente la idea de polución y mancha.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3437', 'spa', 'queja, reproche; motivo o expresión de insatisfacción contra otro', 'Este sustantivo femenino designa una queja, reproche o motivo de censura. En Colosenses 3:13, Pablo instruye a los creyentes a sobrellevarse mutuamente y perdonar si alguno tiene queja contra otro. El uso clásico abarca tanto el acto de quejarse como las razones que lo justifican. El término aparece en contextos de agravio interpersonal donde la paciencia y el perdón se vuelven indispensables. Pablo presupone que surgirán motivos legítimos de queja entre los creyentes; la cuestión no es si habrá ofensas, sino cómo responder ante ellas con gracia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3439', 'spa', 'Unigénito, único en su clase; describe al hijo único de un padre o la relación singular del Hijo con el Padre.', 'Compuesto de μόνος (solo) y γένος (clase, descendencia), este adjetivo describe a alguien que es el único miembro de su especie: un hijo único o un engendrado sin igual. En los Sinópticos, se aplica a hijos únicos de padres afligidos: el hijo único de la viuda de Naín (Lucas 7:12), la hija única de Jairo (Lucas 8:42) y el único hijo de un padre desesperado (Lucas 9:38). En los escritos de Juan adquiere un peso teológico profundo como atributo definitorio de la relación de Jesús con el Padre (Juan 1:14, 18; 3:16, 18; 1 Juan 4:9). El español ''unigénito'' conserva ambos componentes del término griego.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3440', 'spa', 'Solo, solamente, únicamente -- adverbio restrictivo que limita el alcance a un solo elemento, condición o persona.', 'Adverbio derivado de μόνος (''solo, único''), μόνον funciona abrumadoramente como partícula restrictiva que significa ''solo'', ''solamente'' o ''únicamente'', acotando una afirmación a una sola condición, persona o acción. Cuando Jesús dice «solamente di la palabra y mi siervo sanará» (Mt 8:8), μόνον aísla el acto único suficiente. En dos casos excepcionales durante los relatos de la Transfiguración (Mt 17:8; Mr 9:8), el término pasa de la restricción lógica a la soledad física: los discípulos alzaron la vista y vieron «a Jesús solo». El español capta ambos matices con ''solo/solamente''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3441', 'spa', 'Solo, a solas; unico, singular; solamente, exclusivamente (restrictivo)', 'Solo, a solas; unico, singular; solamente, exclusivamente (restrictivo)');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3443', 'spa', 'quedar sola, ser dejada en soledad; encontrarse aislada o privada de compañía y apoyo', 'Este verbo significa dejar sola a una persona o quedar en soledad y aislamiento. En 1 Timoteo 5:5 describe a la viuda verdadera que ha quedado completamente sola, sin apoyo familiar. El uso clásico incluye ser abandonada, quedar aislada en batalla o ser apartada sin testigos. El participio perfecto pasivo enfatiza el estado duradero de soledad y vulnerabilidad que resulta de la pérdida de familiares. Este aislamiento se convierte en el criterio para la asistencia de la iglesia: a diferencia de las viudas con recursos familiares, ella está verdaderamente desamparada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3444', 'spa', 'forma, apariencia externa o manifestación visible', 'Este término designa la forma externa, la apariencia o la manifestación visible de una realidad interior. Marcos relata que Jesús se apareció a dos discípulos «en otra forma» tras la resurrección (Mr 16:12). En el gran pasaje cristológico de Pablo, Cristo existía «en forma de Dios» pero tomó «forma de siervo» (Fil 2:6-7). No se trata de mera apariencia superficial que puede engañar, sino de la manifestación genuina y reconocible de lo que algo verdaderamente es, un punto intermedio entre la apariencia externa y la esencia misma.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3445', 'spa', 'ser formado, moldeado o configurado; recibir forma definida, especialmente la de Cristo en el creyente', 'Este verbo significa dar forma o configuración a algo, o en voz pasiva, recibir forma o ser moldeado. En Gálatas 4:19, Pablo expresa su dolor de parto por los creyentes gálatas hasta que Cristo sea formado en ellos. El uso clásico incluye dar forma al cuerpo o formar soldados. La metáfora paulina sugiere el proceso doloroso mediante el cual el carácter de Cristo toma forma definida en la vida de los creyentes. El aoristo pasivo subjuntivo apunta a una formación completa y definitiva que Pablo anhela presenciar en sus hijos espirituales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3447', 'spa', 'fabricar un becerro; específicamente, elaborar un ídolo con forma de becerro', 'Este verbo compuesto describe específicamente el acto de fabricar un ídolo en forma de becerro. En Hechos 7:41, Esteban relata la apostasía de Israel en el Sinaí: hicieron un becerro y ofrecieron sacrificio al ídolo. El término fue acuñado precisamente para este notorio incidente, combinando «becerro» con «hacer». El discurso de Esteban subraya que mientras Moisés recibía oráculos vivos en la montaña, el pueblo abajo fabricaba un ídolo muerto, rechazando a Dios por la idolatría al estilo egipcio. La intencionalidad del acto queda enfatizada por este verbo específico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3448', 'spa', 'Becerro, novillo; animal bovino joven empleado en sacrificios o celebraciones.', 'Moschos designa un animal bovino joven, ya sea un becerro o novillo, que aparece en el Nuevo Testamento tanto en contextos festivos como sacrificiales. La ocurrencia más memorable se encuentra en la parábola del hijo pródigo, donde el padre ordena matar el becerro gordo para el banquete de bienvenida (Lc 15:23, 27, 30), imagen vívida de acogida generosa y jubilosa. En Hebreos, el término se desplaza al registro sacrificial: la sangre de becerros y machos cabríos era el medio de purificación del Antiguo Pacto (Heb 9:12, 19), ahora superado por la sangre de Cristo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3449', 'spa', 'afán, fatiga, esfuerzo penoso o trabajo arduo', 'Este término denota el trabajo penoso, el esfuerzo agotador y las fatigas propias de una labor exigente. Pablo recuenta sus penalidades apostólicas: «en trabajo y fatiga» (2 Co 11:27). Recuerda a los tesalonicenses que trabajó «noche y día» con «afán y fatiga» para no ser carga para ellos (1 Ts 2:9; 2 Ts 3:8). El énfasis recae en el esfuerzo extenuante y agotador, no en una labor gozosa o productiva. Evoca cansancio físico y desgaste sostenido.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3450', 'spa', 'Yo, pronombre de primera persona (formas adicionales; entrada variante de G3165/G3427)', 'Esta es otra entrada más para el pronombre de primera persona, reflejo de la compleja tradición manuscrita y dialectal del griego. El contenido semántico básico permanece igual: ἐγώ en nominativo para el enfático «yo», con los casos oblicuos derivados de la raíz μ-. La multiplicación de números Strong para este pronombre tan común probablemente se debe a distintas formas flexivas o a variantes de lectura en los manuscritos del Nuevo Testamento.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3451', 'spa', 'hábil en la música, con formación musical; relativo a las artes musicales', 'Este adjetivo describe a una persona diestra en la música o a todo lo relacionado con las artes musicales. En Apocalipsis 18:22, Juan anticipa el silenciamiento de los músicos junto con otros artesanos en el juicio sobre la Babilonia caída. En el uso clásico, el término abarca tanto la habilidad musical propiamente dicha como un sentido más amplio de refinamiento cultural: devotos de las Musas, hombres de letras y artes liberales. En el contexto de Apocalipsis, designa específicamente a músicos profesionales cuyo arte cesará cuando Dios juzgue a la gran ciudad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3452', 'spa', 'médula, el tejido blando del interior de los huesos', 'Este sustantivo masculino designa la médula ósea, el tejido blando que se encuentra en el interior de los huesos. En Hebreos 4:12, aparece en la descripción de la Palabra de Dios como más cortante que toda espada de dos filos, capaz de penetrar hasta la división del alma y el espíritu, las coyunturas y los tuétanos. En el uso clásico incluye tanto la médula en sentido literal como usos metafóricos para referirse a la parte más íntima o la esencia de algo. El emparejamiento con las coyunturas subraya la capacidad de la Palabra para penetrar hasta lo más profundo y oculto de la existencia humana.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3453', 'spa', 'ser iniciado en los misterios; aprender un secreto mediante instrucción o experiencia', 'Este verbo significa primariamente ser iniciado en las religiones de misterio, y por extensión, aprender secretos o ser instruido en un conocimiento oculto. En Filipenses 4:12, Pablo declara haber aprendido el secreto de estar contento en toda circunstancia. En el uso clásico, el término se centra en la iniciación en cultos mistéricos, pero Pablo se apropia de este lenguaje para describir el aprendizaje experiencial del creyente en verdades espirituales, particularmente la contentación independiente de las circunstancias. A diferencia de los misterios paganos con ritos secretos, la iniciación de Pablo vino a través de experiencias fortalecidas por Cristo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3454', 'spa', 'Mito, fábula o relato ficticio; en el NT, siempre con sentido negativo para narrativas religiosas falsas opuestas a la sana doctrina.', 'En el griego clásico, μῦθος significaba simplemente «palabra» o «relato», pero en las Epístolas Pastorales había adquirido un matiz claramente peyorativo. Pablo advierte a Timoteo contra los «mitos y genealogías interminables» (1 Tim 1:4), contrasta el ejercicio piadoso con los «mitos profanos de viejas» (1 Tim 4:7) y predice que la gente se volverá «a los mitos» en vez de soportar la sana enseñanza (2 Tim 4:4). Tito debe reprender a quienes se entregan a «mitos judaicos» (Tit 1:14). Pedro insiste en que los apóstoles no siguieron «mitos ingeniosamente inventados» (2 Pe 1:16).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3455', 'spa', 'rugir, bramar; emitir un sonido fuerte y profundo', 'Este verbo describe el rugido o bramido de animales, particularmente leones, o sonidos fuertes y reverberantes de otras fuentes. En Apocalipsis 10:3, el ángel poderoso clama a gran voz como un león que ruge, y siete truenos hablan en respuesta. En el uso clásico, el término incluye el mugido de bueyes, el rugido de leones o el estruendo de escudos. La palabra enfatiza un sonido potente, resonante e imponente que exige atención y transmite autoridad, poder y majestad sobrecogedora, propio de una proclamación cósmica que estremece la creación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3456', 'spa', 'burlarse, mofarse, tratar con desprecio', 'Este verbo significa literalmente arrugar la nariz ante alguien, y por extensión burlarse, mofarse o tratar con desprecio. En Gálatas 6:7, Pablo advierte que nadie se engañe: de Dios nadie se burla. En el uso clásico, el término evoca el gesto físico de levantar la nariz con desdén, extendiéndose a cualquier trato despectivo. La advertencia de Pablo se dirige a quienes piensan que pueden despreciar el orden moral de Dios sin consecuencias. La forma pasiva subraya que Dios no es alguien de quien uno pueda burlarse impunemente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3457', 'spa', 'relativo a un molino; piedra de molino, usada para moler grano', 'Este adjetivo describe algo relacionado con un molino, particularmente una piedra de molino usada para moler grano. En Lucas 17:2, Jesús advierte que sería mejor que le colgaran una piedra de molino al cuello y lo arrojaran al mar, antes que hacer tropezar a uno de estos pequeños. Las glosas multilingües identifican la piedra de molino (español de molino, francés meule). La imagen evoca las grandes piedras que giraban para triturar el grano, lo suficientemente pesadas como para asegurar el ahogamiento. Jesús emplea esta impactante imagen para subrayar la gravedad de causar daño espiritual a los creyentes vulnerables.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3458', 'spa', 'Molino o piedra de molino; piedra pesada para moler grano, frecuentemente símbolo de juicio catastrófico', 'Designa tanto el aparato de molienda como la piedra misma. Jesús invoca la piedra de molino en una advertencia sobrecogedora: sería mejor que le colgaran una gran piedra de molino al cuello y lo arrojaran al mar, antes que hacer tropezar a uno de estos pequeños (Mt 18:6; Mr 9:42). En la visión apocalíptica, un ángel poderoso lanza una piedra «semejante a una gran piedra de molino» al mar para dramatizar la caída de Babilonia, y el sonido del molino no se oye más (Ap 18:21-22). En español se distingue entre ''piedra de molino'' (la piedra) y ''molino'' (el lugar), reflejando ambas dimensiones. El objeto doméstico cotidiano se convierte en poderosa imagen del juicio divino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3459', 'spa', 'Molino, lugar donde se muele el grano; también metáfora de trabajo arduo y penoso', 'El μυλών es un molino o casa de molienda donde se tritura el grano para convertirlo en harina. El término aparece en contextos de trabajo manual y castigo: condenar a un esclavo «al molino» significaba sentenciarlo a la agotadora tarea de moler grano. Un ingenioso autor antiguo llamó a los trirremes «molinos pintados», aludiendo al esfuerzo repetitivo y extenuante de remar. El molino representa tanto la producción doméstica necesaria como el duro trabajo servil.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3460', 'spa', 'Mira, ciudad importante y puerto de Licia en el sur de Asia Menor', 'Este nombre propio designa una importante ciudad costera de Licia donde Pablo cambió de embarcación durante su viaje a Roma. En Hechos 27:5, Lucas registra su llegada a Mira tras navegar por el mar frente a Cilicia y Panfilia. Las glosas multilingües simplemente transliteran el topónimo. Mira era un puerto significativo para los barcos que viajaban entre el Mediterráneo oriental y Roma, lo que la convertía en un punto natural de trasbordo. Los restos arqueológicos revelan su importancia como centro comercial y cultural en la antigüedad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3461', 'spa', 'Miríada, diez mil; número inmenso usado hiperbólicamente para una multitud innumerable o un ejército celestial.', 'Literalmente diez mil, pero en el uso común un término para cualquier cantidad incalculablemente grande. El Nuevo Testamento lo emplea tanto en conteos aproximados (la deuda de diez mil talentos en Mateo 18:24 y los cincuenta mil piezas de plata en libros de magia quemados en Éfeso en Hechos 19:19) como para huestes verdaderamente innumerables, como cuando Hebreos 12:22 describe ''miríadas de ángeles'' en la asamblea celestial. Judas 1:14 cita la profecía de Enoc de que el Señor viene ''con sus decenas de millares de santos''. El español ''miríadas'' conserva directamente el préstamo del griego.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3462', 'spa', 'ungir con aceite perfumado o mirra, especialmente como preparación para la sepultura', 'Este verbo significa frotar con ungüento o aceite perfumado, ungir. En Marcos 14:8, Jesús defiende a la mujer que lo ungió, declarando que ella ha ungido de antemano su cuerpo para la sepultura. Las glosas multilingües identifican la acción de ungir (español ungir, francés oindre, alemán salben). El uso clásico incluye tanto la unción cosmética como aplicaciones ceremoniales. Jesús reinterpreta el acto generoso de la mujer como preparación profética para su sepultura, aunque ella probablemente pretendía honrar al rey viviente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3463', 'spa', 'diez mil, incontable, una miríada o número muy grande', 'Una miríada equivale a diez mil, pero frecuentemente se usa para expresar una cantidad incontablemente grande. En la parábola de Jesús, un siervo debe «diez mil talentos», una deuda hiperbólica e imposible de pagar (Mt 18:24). Pablo dice que preferiría hablar cinco palabras comprensibles antes que «diez mil» en lengua desconocida (1 Co 14:19), y señala a los corintios que pueden tener «incontables» guías pero un solo padre espiritual (1 Co 4:15). El término enfatiza una vastedad que sobrepasa todo cálculo fácil.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3464', 'spa', 'Ungüento, aceite perfumado, preparación aromática costosa usada para ungir y para la sepultura. Μύρον designa el costoso ungüento aromático que aparec', 'Ungüento, aceite perfumado, preparación aromática costosa usada para ungir y para la sepultura. Μύρον designa el costoso ungüento aromático que aparece en algunos de los momentos más íntimos y teológicamente cargados de los Evangelios. Cuando una mujer quiebra un frasco de alabastro sobre la cabeza de Jesús (Mt 26:7; Mc 14:3) o lo derrama sobre sus pies y los seca con su cabello (Lc 7:38; Jn 11:2; 12:3), es μύρον lo que usa — costoso, fragante y destinado a huéspedes de honor o a la preparación de los muertos. La protesta de los discípulos por el derroche (Mc 14:4-5; Jn 12:5) subraya la extravagancia. En Ap 18:13 aparece en el inventario comercial de Babilonia junto a la canela y el incienso, confirmando su estatus como mercancía de alto valor.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3466', 'spa', 'Misterio, secreto — una verdad divina antes oculta pero ahora revelada por medio de Cristo y la proclamación apostólica', 'Misterio, secreto — una verdad divina antes oculta pero ahora revelada por medio de Cristo y la proclamación apostólica');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3467', 'spa', 'ser corto de vista, incapaz de ver con claridad a distancia; metafóricamente, carecer de percepción espiritual', 'Este verbo describe la condición de ser miope o corto de vista, ya sea literal o metafóricamente. En 2 Pedro 1:9, caracteriza a la persona carente de virtudes cristianas como ciega o corta de vista, habiendo olvidado la purificación de sus pecados pasados. Las glosas multilingües identifican la miopía o cortedad de vista (español corto de vista, formas en francés y alemán). El término significa literalmente parpadear o entrecerrar los ojos como una persona miope que se esfuerza por ver. Pedro lo emplea metafóricamente para describir la ceguera espiritual ante las realidades presentes y la esperanza futura.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3468', 'spa', 'herida, verdugón o moretón; marca dejada por un golpe o azote, especialmente de la flagelación de Cristo', 'Pedro utiliza este término médico para evocar la violencia de la pasión de Cristo: «por cuya herida fuisteis sanados» (1 Pedro 2:24). El griego denota no solo una lesión sino la marca visible que deja: un verdugón, moretón o coágulo producido por un golpe. En la literatura clásica el vocablo aparece en textos médicos describiendo erupciones cutáneas y contusiones. La cita de Isaías 53 que hace Pedro transforma un término clínico en una paradoja teológica: las heridas físicas infligidas al Siervo Sufriente se convierten en el medio de restauración espiritual para los creyentes.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3470', 'spa', 'mancha moral, defecto o fuente de reproche; persona que acarrea deshonra o vergüenza a la comunidad', 'En 2 Pedro 2:13, este término señala a los falsos maestros como ''manchas'' (μῶμοι) que contaminan las comidas de comunión de la iglesia. El griego clásico emplea la palabra tanto para defectos físicos como para el reproche moral: una mancha sobre la reputación o una deshonra para la comunidad. La idea de fondo es algo que deteriora la pureza o la integridad, ya sea en un animal de sacrificio o en el carácter humano. La retórica de Pedro es contundente: estos engañadores no solo están equivocados, sino que contaminan activamente la asamblea reunida.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3471', 'spa', 'Hacer necio, volver insípido; perder el sabor o quedar sin propósito', 'Verbo de doble filo: en voz activa significa hacer necio o entontecer, y en voz pasiva, volverse insípido y perder toda utilidad. Jesús emplea la metáfora de la sal en Mateo 5:13 y Lucas 14:34: si la sal pierde su sabor (μωρανθῇ), para nada sirve ya, imagen vívida del discipulado que ha perdido su cualidad distintiva. Pablo despliega el sentido activo-causal en Romanos 1:22 y 1 Corintios 1:20, proclamando que Dios «ennequeció» la sabiduría del mundo. Las traducciones al español reflejan bien ambos polos semánticos: ''se desvaneciere'' para lo insípido y ''se hicieron necios'' para la insensatez.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3472', 'spa', 'Necedad, insensatez; la cualidad de ser absurdo o carente de juicio, usado por Pablo para describir la paradoja del evangelio', 'Sustantivo que denota necedad o insensatez: el estado de carecer de juicio o sabiduría. Pablo emplea esta palabra con llamativa ironía en 1 Corintios, donde la «necedad» del mensaje de Dios mediante la cruz confunde la sabiduría del mundo (1 Co 1:18, 21). Las cinco apariciones neotestamentarias se concentran en esa misma carta, edificando una paradoja sostenida: lo que el mundo considera μωρία resulta ser poder de Dios. En 1 Co 3:19 los papeles se invierten: la sabiduría mundana es declarada necedad ante Dios. El español ''necedad'' capta con precisión esa noción de absurdo cognitivo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3473', 'spa', 'habla necia o insensata; conversación carente de sabiduría, discernimiento o seriedad moral', 'Pablo condena la ''palabrería necia'' (μωρολογία) junto con las bromas groseras en Efesios 5:4, como algo impropio entre los santos. El compuesto une ''necedad'' (μωρός) y ''palabra'' (λόγος), designando un hablar que no es meramente trivial sino moralmente vacío: conversación que ni edifica ni honra a Dios. En el uso clásico, el término connota parloteo sin sentido o hablar sin entendimiento. Las listas de vicios de Pablo apuntan tanto a los pecados de la lengua como a los de obra, porque el habla tanto revela como moldea el corazón.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3474', 'spa', 'μωρός — necio, insensato; falto de sabiduría o buen juicio, torpe moral o intelectualmente. El adjetivo μωρός (''necio, insensato'') describe a alguien ', 'μωρός — necio, insensato; falto de sabiduría o buen juicio, torpe moral o intelectualmente. El adjetivo μωρός (''necio, insensato'') describe a alguien o algo desprovisto de cordura, sabiduría o juicio sensato. En el griego clásico abarcaba desde la torpeza física hasta la necedad intelectual; en el Nuevo Testamento adquiere connotaciones morales y espirituales más agudas. Jesús lo usa para condenar el insulto vacío (Mt 5:22), para caracterizar al hombre que edifica sobre la arena (Mt 7:26) y para distinguir a las cinco vírgenes desprevenidas (Mt 25:2-3). Su severa reprensión a los escribas y fariseos — ''¡Necios y ciegos!'' (Mt 23:17) — lo empuña como veredicto de ceguera espiritual. Pablo invierte su vergüenza en 1 Co 1:25, declarando que ''lo insensato de Dios es más sabio que los hombres,'' reclamando el término como paradoja de la sabiduría divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3475', 'spa', 'Moisés, el legislador y profeta que sacó a Israel de Egipto y recibió la Torá en el Sinaí', 'Moisés es la figura central de la Torá, el profeta por medio del cual Dios liberó a Israel de Egipto y estableció el pacto sinaítico. En el Nuevo Testamento su nombre aparece de dos maneras principales: como personaje histórico que habló con Jesús en la Transfiguración (Mt 17:3) y como metonimia del Pentateuco y su autoridad legal («la ley de Moisés», Lc 24:44; Hch 15:21). La imagen paulina del velo en 2 Corintios 3:15 —«cuando se lee a Moisés»— ilustra el paso fluido de persona a texto, fusión arraigada en el pensamiento judío y cristiano primitivo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3476', 'spa', 'Naasón, hijo de Aminadab, antepasado de David y de Jesús', 'Naasón (en hebreo נַחְשׁוֹן) fue hijo de Aminadab y padre de Salmón, y aparece en las genealogías de David y de Jesús. Fue líder de la tribu de Judá durante la peregrinación por el desierto (Nm 1:7). Tanto Mateo como Lucas lo incluyen en la línea ancestral de Jesús (Mt 1:4; Lc 3:32). Su nombre se ha transliterado de manera consistente en las diversas lenguas, conservando la forma del original hebreo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3477', 'spa', 'Nangaí, antepasado de Jesús mencionado en la genealogía de Lucas', 'Nangaí aparece únicamente en Lucas 3:25, como parte de la cadena genealógica que traza el linaje de Jesús desde David hasta Adán. Como muchos nombres en la sección postexílica de la genealogía lucana, Nangaí es desconocido en otras fuentes bíblicas o extrabíblicas. El nombre podría derivar de una raíz hebrea relacionada con brillo o luz, aunque su etimología permanece incierta. La inclusión por parte de Lucas de antepasados oscuros subraya la continuidad providencial que vincula a Jesús con la historia del pacto de Israel, incluso a través de generaciones olvidadas por otros registros.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3478', 'spa', 'Nazaret — la ciudad galileana donde Jesús se crió, también escrita Nazará. Nazaret (Nazareth/Nazará) es la pequeña ciudad de la baja Galilea donde viv', 'Nazaret — la ciudad galileana donde Jesús se crió, también escrita Nazará. Nazaret (Nazareth/Nazará) es la pequeña ciudad de la baja Galilea donde vivían María y José y donde Jesús creció. A pesar de su oscuridad — el desdeñoso comentario de Natanael ''¿De Nazaret puede salir algo bueno?'' (Jn 1:46) refleja su reputación — llegó a ser uno de los topónimos más reconocidos de la historia. Los manuscritos del Nuevo Testamento conservan múltiples grafías (Nazareth, Nazaret, Nazará), que reflejan variación de transliteración del semítico al griego, no ubicaciones distintas. Lucas sitúa allí la Anunciación (1:26), y Mateo la identifica como cumplimiento de una palabra profética: ''Será llamado nazareno'' (2:23). Cada lengua de destino conserva el nombre con solo una mínima adaptación fonológica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3479', 'spa', 'Nazareno; designación que identifica a Jesús como originario de Nazaret en Galilea.', 'Título gentilicio que significa ''oriundo de Nazaret'', usado exclusivamente en Marcos y Lucas para identificar a Jesús por su ciudad natal. En boca de los demonios (Mc 1:24, Lc 4:34) conlleva un tono de reconocimiento y alarma, mientras que en el habla ordinaria simplemente ubica a Jesús geográficamente. La forma semítica Nazarenos (en lugar del patrón ático) refleja el entorno aramaico de Galilea, como señaló Dalman. Tras la resurrección, el título persiste (Mc 16:6), ahora cargado de un significado más profundo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3480', 'spa', 'Nazareno; designación que significa ''de Nazaret,'' aplicada a Jesús como título y a sus seguidores como grupo. Adjetivo gentilicio convertido en título', 'Nazareno; designación que significa ''de Nazaret,'' aplicada a Jesús como título y a sus seguidores como grupo. Adjetivo gentilicio convertido en título virtual, que significa ''el de Nazaret.'' Aplicado casi exclusivamente a Jesús a lo largo de los Evangelios y Hechos, lo identifica por su pueblo natal — la oscura aldea galileana de la que Natanael preguntó: ''¿De Nazaret puede salir algo bueno?'' (Jn 1:46). Mateo 2:23 ve en el nombre el cumplimiento de una profecía: ''Será llamado nazareno.'' El título aparece en la inscripción de la cruz (Jn 19:19), en el sermón de Pedro en Pentecostés (Hch 2:22), en fórmulas apostólicas de sanación (Hch 3:6; 4:10) e incluso en labios del Cristo resucitado identificándose ante Pablo (Hch 22:8). En Hechos 24:5 se extiende a los seguidores de Jesús como ''la secta de los nazarenos,'' mostrando cómo una etiqueta geográfica se convirtió en marca confesional.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3481', 'spa', 'Natán, profeta durante los reinados de David y Salomón, y antepasado de Jesús en la genealogía de Lucas', 'El nombre Natán (del hebreo ''él ha dado'') pertenece principalmente al profeta que confrontó a David por el asunto de Betsabé (2 Samuel 12). Sin embargo, en Lucas 3:31, Natán es identificado como hijo de David y antepasado en el linaje de Jesús, distinto del profeta más conocido. Este Natán aparece en 1 Crónicas 3:5 como uno de los hijos nacidos a David en Jerusalén. La genealogía de Lucas traza la línea de Jesús a través de Natán en lugar de Salomón, divergiendo de la línea real de Mateo y enfatizando posiblemente un linaje no real a través de María o una herencia legal diferente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3482', 'spa', 'Natanael; discípulo de Jesús, probablemente identificable con Bartolomé', 'Nombre hebreo indeclinable que significa ''Dios ha dado'' (de natan + El), llevado por el discípulo que Felipe trajo a Jesús en Juan 1:45-49. El escepticismo inicial de Natanael (''¿De Nazaret puede salir algo bueno?'') se transforma en una confesión dramática cuando Jesús revela un conocimiento sobrenatural de él bajo la higuera. Reaparece en Juan 21:2 en la escena de pesca posterior a la resurrección, identificado como originario de Caná de Galilea. La mayoría de los eruditos lo identifican con el Bartolomé de las listas sinópticas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3483', 'spa', 'Si; ciertamente; particula afirmativa que expresa fuerte acuerdo, asentimiento o confirmacion solemne', 'Si; ciertamente; particula afirmativa que expresa fuerte acuerdo, asentimiento o confirmacion solemne');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3484', 'spa', 'Naín, aldea de Galilea donde Jesús resucitó al hijo de una viuda', 'Naín se encuentra en el sur de Galilea, cerca del monte Tabor, a unos diez kilómetros al sureste de Nazaret. Lucas 7:11-17 relata la compasión de Jesús al encontrarse con una procesión fúnebre: el hijo único de una viuda era llevado a enterrar. Jesús tocó el féretro, ordenó al joven que se levantara y lo devolvió a su madre, un acto que evoca la resurrección del hijo de la viuda de Sarepta por Elías (1 Reyes 17:17-24). El nombre de la aldea podría derivar de una raíz hebrea que significa ''agradable'' o ''pastizal''. Este milagro prefigura la resurrección mayor que el propio Jesús experimentaría y valida su identidad como el profeta prometido, mayor que Elías.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3485', 'spa', 'Templo, santuario; el recinto interior de la morada de Dios, o un modelo de santuario pagano', 'Templo, santuario; el recinto interior de la morada de Dios, o un modelo de santuario pagano');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3486', 'spa', 'Nahúm (del hebreo ''consolado''), antepasado de Jesús mencionado en la genealogía de Lucas', 'Nahúm aparece en Lucas 3:25 como parte de la cadena genealógica postexílica que vincula a Jesús con David y Abraham. El nombre es idéntico al del profeta menor Nahúm, quien profetizó la caída de Nínive en el siglo VII a.C., aunque el Nahúm genealógico es un individuo distinto. En hebreo, el nombre significa ''consuelo'' o ''consolación'', compartiendo raíz con Nehemías y el verbo נחם (nacham). La inclusión por parte de Lucas de antepasados por lo demás desconocidos subraya la particularidad histórica de la encarnación de Jesús: el Mesías de Dios viene a través de personas reales en tiempo real, no mediante mitos ni leyendas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3488', 'spa', 'Narciso, romano cuyo hogar incluía creyentes a quienes Pablo envió saludos', 'En Romanos 16:11, Pablo envía saludos a ''los de la casa de Narciso que están en el Señor''. El nombre era común en Roma, y algunos estudiosos identifican a este Narciso con Tiberio Claudio Narciso, un liberto adinerado e influyente bajo el emperador Claudio. De ser así, sus esclavos y dependientes habrían formado un grupo considerable, algunos de los cuales habían llegado a la fe en Cristo. La palabra griega también designa la flor del narciso, conocida en la antigüedad por sus propiedades narcóticas, de donde proviene la figura mitológica que se enamoró de su propio reflejo. El saludo de Pablo pone de manifiesto la penetración del evangelio en hogares romanos influyentes, incluso aquellos vinculados a la corte imperial.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3490', 'spa', 'naviero, capitán de barco o patrón de embarcación responsable de la navegación y operación de un navío', 'En Hechos 27:11, el centurión romano Julio atiende al consejo del capitán del barco (ναύκληρος) y del piloto en lugar de la advertencia de Pablo de no zarpar. El término originalmente designaba al propietario de un barco que también lo capitaneaba como navío mercante, aunque más tarde podía referirse a cualquier patrón de embarcación. Las fuentes clásicas distinguen al ναύκληρος del timonel (κυβερνήτης), encargado de la dirección, y del mercader (ἔμπορος), dueño de la carga. La narración de Lucas muestra al centurión defiriendo al juicio marítimo profesional, una decisión razonable que sin embargo conduce al barco hacia la tempestad que Pablo había predicho.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3491', 'spa', 'nave o embarcación marítima, especialmente las usadas para comercio o guerra en el Mediterráneo antiguo', 'Hechos 27:41 describe el momento en que la nave de Pablo encalla en Malta: ''dieron en un banco de arena y la nave (ναῦς) se rompió por la violencia de las olas''. Aunque el término más habitual para barco en el Nuevo Testamento es πλοῖον, Lucas emplea aquí la voz clásica y poética ναῦς, quizá por variación estilística o para evocar la literatura épica de navegación. En Homero y los textos clásicos, ναῦς aparece con frecuencia en descripciones de batallas navales y viajes heroicos. La declinación ática de esta palabra es notoriamente irregular, un rasgo que sobrevive en el único uso lucano de la forma acusativa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3492', 'spa', 'marineros, navegantes, hombres de mar', 'Este término designa a los marineros, es decir, quienes trabajan a bordo de embarcaciones como profesionales del mar. Lucas describe a los «marineros» del barco de Pablo intentando abandonar la nave durante la tempestad (Hch 27:27, 30). En la visión apocalíptica de Juan, los marineros lamentan la caída de Babilonia, llorando la pérdida de su sustento (Ap 18:17). El vocablo designa de forma constante a quienes tienen la navegación como oficio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3493', 'spa', 'Nacor, abuelo de Abraham y antepasado de Jesús en la genealogía de Lucas', 'Nacor aparece en Lucas 3:34 como hijo de Serug y padre de Taré, situándolo dos generaciones antes de Abraham. Génesis 11:22-25 registra que Nacor vivió 148 años y engendró a Taré a los 29. El nombre pertenece también al hermano de Abraham (Génesis 11:26-27), lo que ocasiona confusiones en discusiones genealógicas. En hebreo, Nacor (נָחוֹר) podría derivar de una raíz que significa ''resoplar'' o ''roncar'', aunque la etimología es incierta. La inclusión lucana de estos nombres antediluvianos y patriarcales enraíza el linaje de Jesús en el pasado remoto, trazando la historia pactual de Israel hasta los albores de la civilización humana.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3494', 'spa', 'joven, hombre joven, varón en el vigor de la primera adultez', 'Un νεανίας es un varón joven, ya pasada la niñez pero aún no asentado en la madurez plena. Los testigos depositaron sus mantos a los pies de «un joven llamado Saulo» durante la lapidación de Esteban (Hch 7:58). Eutico, «un joven», cayó de una ventana mientras Pablo predicaba extensamente (Hch 20:9). Pablo fue advertido por «el hijo de la hermana de Pablo, un joven» sobre una emboscada (Hch 23:17). El término señala esa etapa de energía y vigor propia de la juventud masculina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3495', 'spa', 'El sustantivo νεανίσκος (neaniskos) designa a un hombre joven, aproximadamente entre la adolescencia y la plena madurez. El joven rico que pregunta a ', 'El sustantivo νεανίσκος (neaniskos) designa a un hombre joven, aproximadamente entre la adolescencia y la plena madurez. El joven rico que pregunta a Jesús sobre la vida eterna es un νεανίσκος (Mt 19:20, 22), al igual que el joven anónimo que huye desnudo de Getsemaní (Mr 14:51), un detalle exclusivo de Marcos y objeto de interminables debates. En la tumba vacía, las mujeres encuentran a un νεανίσκος vestido con una túnica blanca (Mr 16:5), probablemente una figura angélica, aunque la elección de Marcos de este término humano resulta llamativa. Lucas lo usa para referirse al hijo muerto de la viuda de Naín, a quien Jesús resucita (Lc 7:14), y Hechos registra a Pedro citando la profecía de Joel de que ''vuestros jóvenes verán visiones'' (Hch 2:17). El español ''joven'' y el francés ''jeune homme'' captan el rango de edad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3496', 'spa', 'Neápolis, «ciudad nueva» (nombre propio de varias ciudades del mundo griego)', 'Νεάπολις («Ciudad Nueva») era un nombre frecuente para las fundaciones griegas en todo el Mediterráneo, comparable a «Villanueva» en español. Varias ciudades llevaron este nombre desde el siglo V a. C. en adelante. La forma unificada posterior Νεάπολις (genitivo Νεαπόλεως) reemplazó la construcción original de dos palabras. Sus habitantes se llamaban Νεοπολίται o, más tarde, Νεαπολῖται. El nombre refleja la expansión colonial griega y el optimismo al fundar nuevos asentamientos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3497', 'spa', 'Naamán, el comandante sirio sanado de lepra por Eliseo, citado por Jesús como ejemplo de la misericordia de Dios hacia los gentiles', 'Jesús menciona a Naamán el sirio en Lucas 4:27 durante su sermón en Nazaret: ''Muchos leprosos había en Israel en tiempos de Eliseo, pero ninguno fue limpiado sino Naamán el sirio.'' El relato original de 2 Reyes 5 narra cómo este poderoso oficial militar, afligido por una enfermedad cutánea, buscó sanación del profeta Eliseo. A pesar de su resistencia inicial al sencillo mandato de lavarse en el Jordán, Naamán obedeció y fue purificado. La alusión de Jesús provoca a su audiencia natal al sugerir que el favor divino se extiende más allá del Israel étnico, tema que dominará Lucas-Hechos. Naamán se convierte en figura del gentil que recibe la gracia divina mediante la fe humilde.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3498', 'spa', 'Muerto — como sustantivo, los muertos (difuntos colectivamente); como adjetivo, sin vida, en sentido literal o figurado', 'Νεκρός figura entre las palabras con mayor carga teológica del Nuevo Testamento, al situarse en el corazón de la afirmación central del cristianismo: la resurrección de entre los muertos. Como sustantivo (''los muertos'') designa el ámbito colectivo de los difuntos del cual Cristo resucitó y los creyentes resucitarán (1 Co 15:12-21). Como adjetivo describe tanto la muerte literal — el joven de Naín (Lc 7:15), Eutico tras su caída (Hch 20:9) — como un poderoso estado figurado: el hijo pródigo estaba ''muerto y ha vuelto a vivir'' (Lc 15:24, 32), y Santiago declara que la fe sin obras está ''muerta'' (Stg 2:26). Español muerto preserva esta misma flexibilidad sustantivo-adjetivo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3499', 'spa', 'dar muerte, mortificar, hacer morir o dejar sin efecto', 'Mortificar significa dar muerte o dejar sin poder algo. El cuerpo de Abraham estaba «ya como muerto» (Ro 4:19), pero él creyó la promesa de Dios. Pablo ordena: «Haced morir lo terrenal en vosotros» (Col 3:5), es decir, mortificad los deseos pecaminosos. Hebreos habla de Sara que concibió de uno «ya como muerto» (Heb 11:12). El término oscila entre un estado literal de muerte física y la aniquilación metafórica del pecado, abarcando tanto la condición pasiva como la acción deliberada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3501', 'spa', 'Joven, juvenil; nuevo, fresco, recién hecho; Nea (elemento de topónimo que significa «nueva»)', 'Joven, juvenil; nuevo, fresco, recién hecho; Nea (elemento de topónimo que significa «nueva»)');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3502', 'spa', 'crías de ave, polluelos o pichones; usado figuradamente para niños o seres que requieren cuidado y protección', 'Lucas 2:24 señala que María y José ofrecieron ''un par de tórtolas o dos pichones (νοσσούς)'' en la presentación de Jesús en el templo, cumpliendo el requisito de purificación de Levítico 12:8 para quienes no podían costear un cordero. El término designa aves recién nacidas o muy jóvenes, aún dependientes del cuidado parental. En el griego clásico, la metáfora se extiende a infantes humanos y crías de otros animales. La ofrenda indica la pobreza de María y su obediencia a la ley. El reconocimiento del niño Jesús por Simeón y Ana añade ironía: los padres traen el sacrificio de los pobres, sin saber que presentan al Cordero de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3503', 'spa', 'Juventud; el período de la vida temprana o la condición de ser joven', 'Designa la etapa de la vida que abarca desde la niñez hasta la adultez temprana, invocada con frecuencia cuando alguien reflexiona sobre un compromiso prolongado. El joven rico le dice a Jesús que ha guardado los mandamientos «desde mi juventud» (Mr 10:20; Lc 18:21), y Pablo traza igualmente su historia de vida remontándose a su juventud entre su nación (Hch 26:4). Timoteo recibe la aplicación inversa: que nadie menosprecie tu juventud (1 Ti 4:12), convirtiendo la palabra de una mirada retrospectiva en un desafío presente. El español ''juventud'' y el francés ''jeunesse'' convergen en este único sentido temporal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3504', 'spa', 'recién plantado o recién convertido; un nuevo creyente o converso reciente a la fe', 'Pablo advierte a Timoteo en 1 Timoteo 3:6 que no designe a un recién convertido (νεόφυτος) como obispo, no sea que se envanezca y caiga en la condenación del diablo. El término significa literalmente ''recién plantado'', evocando la imagen agrícola de un retoño que aún no ha echado raíces firmes. En el uso clásico, la palabra se aplica a plantas jóvenes y plántulas. La preocupación de Pablo es práctica: la madurez espiritual requiere tiempo. Un nuevo creyente carece del carácter probado, la solidez doctrinal y la humildad necesarias para el liderazgo eclesial. Una elevación prematura puede truncar el crecimiento e invitar al desastre, tanto para el individuo como para la congregación encomendada a su cuidado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3505', 'spa', 'Nerón, emperador romano (nombre propio; reinado 54-68 d. C.)', 'Nombre del emperador romano que gobernó del 54 al 68 d. C. Nerón aparece en la suscripción del Texto Recibido a 2 Timoteo, aunque esto refleja una tradición escribal posterior y no la composición paulina original. Su reinado fue testigo tanto de mecenazgo cultural como de la infame persecución de los cristianos tras el Gran Incendio de Roma en el año 64 d. C. El nombre proviene de una palabra sabina que significa «fuerte» o «vigoroso».');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3507', 'spa', 'Nube; masa de vapor atmosférico que a menudo indica la presencia velada o la gloria de Dios en contextos teofánicos y escatológicos', 'Nube; masa de vapor atmosférico que a menudo indica la presencia velada o la gloria de Dios en contextos teofánicos y escatológicos');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3508', 'spa', 'Neftalí, hijo de Jacob, tribu de Israel y su territorio tribal', 'Neftalí (hebreo נַפְתָּלִי) fue el sexto hijo de Jacob, nacido de Bilha, sierva de Raquel. Sus descendientes formaron una de las doce tribus de Israel, con territorio en el norte de Galilea. Mateo cita a Isaías identificando la región del ministerio de Jesús como «la tierra de Neftalí» (Mt 4:13, 15). Apocalipsis incluye a Neftalí entre las tribus selladas (Ap 7:6). El nombre significa «mi lucha», en recuerdo del conflicto de Raquel. La transliteración se mantiene consistente en diversas lenguas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3509', 'spa', 'nube o gran aglomeración; usado literalmente para nubes atmosféricas o metafóricamente para multitudes', 'Hebreos 12:1 abre con una poderosa metáfora: ''Por tanto, teniendo en derredor nuestro tan gran nube (νέφος) de testigos, despojémonos de todo peso y del pecado que nos asedia.'' El término designa una nube densa o masa compacta, utilizado en el griego clásico para nubes atmosféricas, enjambres de personas o concentraciones densas de cualquier cosa. El autor presenta a los fieles de Hebreos 11 como una multitud en un anfiteatro que observa la carrera cristiana. Su testimonio, registrado en las Escrituras y vindicado por Dios, alienta y a la vez interpela. La imagen combina cercanía (testigos que se interesan) con grandeza (una muchedumbre innumerable que abarca generaciones).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3510', 'spa', 'los riñones; usado metafóricamente en la literatura bíblica para designar la sede más íntima de las emociones y el discernimiento moral', 'Apocalipsis 2:23 contiene la declaración del Cristo resucitado a la iglesia de Tiatira: ''Yo soy el que escudriña los corazones y los riñones (νεφρούς), y daré a cada uno según sus obras.'' En la antropología hebrea, los riñones representan la vida interior más profunda: deseos, motivaciones y conciencia, junto al corazón o como sinónimo de él. La metáfora aparece en el Antiguo Testamento (Salmos 7:9; Jeremías 11:20), en contextos de juicio divino. El griego clásico emplea el término para los órganos físicos, pero el uso bíblico se nutre del pensamiento semítico. Cristo proclama su omnisciencia: nada escapa a su mirada, ni siquiera las intenciones más secretas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3511', 'spa', 'guardián del templo, custodio del santuario; título honorífico de una ciudad que albergaba un templo imperial o de una deidad', 'En Hechos 19:35, el secretario de Éfeso defiende el estatus de la ciudad: ''¿Quién no sabe que la ciudad de los efesios es guardiana (νεωκόρος) del templo de la gran Artemisa y de la imagen caída del cielo?'' El término originalmente designaba al servidor o sacristán encargado de mantener un santuario. En el período imperial, las ciudades griegas competían por el título honorífico de νεωκόρος, otorgado a aquellas que construían templos para el culto imperial o para deidades principales. Éfeso se enorgullecía de este estatus por el Artemisión, una de las Siete Maravillas del mundo antiguo. El discurso del secretario busca calmar el tumulto recordando que el honor de Éfeso está asegurado y que Pablo no representa una amenaza real.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3512', 'spa', 'juvenil, propio de la juventud; especialmente las pasiones, impulsos o vicios asociados con los jóvenes', 'Pablo exhorta a Timoteo en 2 Timoteo 2:22: ''Huye de las pasiones juveniles (νεωτερικὰς ἐπιθυμίας) y sigue la justicia, la fe, el amor y la paz.'' El adjetivo designa lo que es natural o típico de la juventud, no necesariamente pecaminoso en sí mismo, pero propenso al exceso y la inmadurez. El uso clásico aplica el término al vigor juvenil, la impetuosidad y la falta de disciplina. Timoteo, aunque quizás rondaba los treinta años, aún era ''joven'' en relación con su rol de liderazgo y los miembros mayores de su congregación. El consejo de Pablo es pastoral: reconoce las vulnerabilidades propias de tu etapa de vida, guárdate de la impulsividad y cultiva las virtudes maduras de una fe sólida.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3513', 'spa', 'partícula de afirmación solemne usada en juramentos, ''por'' o ''juro por'' (seguida del objeto invocado)', 'Pablo emplea un juramento solemne en 1 Corintios 15:31: ''Cada día muero —lo juro por (νή) el orgullo que tengo en vosotros en Cristo Jesús, Señor nuestro.'' La partícula νή introduce juramentos en el griego clásico, seguida del nombre de un dios o un objeto sagrado. Los oradores atenienses juraban ''por Zeus'' (νὴ Δία) para enfatizar la veracidad de sus declaraciones. Pablo adapta la fórmula jurando no por una deidad sino por su legítimo orgullo apostólico en los corintios, afirmando su declaración y recordándoles su identidad como hijos espirituales suyos. El juramento subraya que la resurrección es el corazón del evangelio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3515', 'spa', 'ser o actuar como un niño pequeño; comportarse de manera infantil o inmadura', 'Pablo formula un mandato matizado en 1 Corintios 14:20: ''Hermanos, no seáis niños (νηπιάζετε) en el modo de pensar. En cuanto a la malicia, sed niños, pero en el pensar, sed maduros.'' El verbo deriva de νήπιος (''infante'' o ''niño'') y denota un comportamiento infantil. La retórica de Pablo es paradójica: la infantilidad en el pensamiento es un defecto (falta de comprensión, susceptibilidad al error), pero la inocencia infantil frente al mal es una virtud (ausencia de malicia). La obsesión de los corintios con los dones espirituales vistosos revela inmadurez intelectual y espiritual. Pablo los llama a crecer, a buscar el amor y la edificación en lugar de la exhibición personal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3516', 'spa', 'Infante, niño pequeño; en sentido figurado, alguien espiritualmente inmaduro o, raramente, tierno y delicado. Originalmente referido a un bebé o niño ', 'Infante, niño pequeño; en sentido figurado, alguien espiritualmente inmaduro o, raramente, tierno y delicado. Originalmente referido a un bebé o niño pequeño, este adjetivo-sustantivo abarca desde la cuna hasta el carácter. Jesús alaba al Padre por revelar la verdad a los ''niños'' en lugar de a los sabios (Mt 11:25; Lc 10:21), y los Salmos celebran la alabanza de la boca de los lactantes (Mt 21:16). Pablo reutiliza la palabra para reprender la inmadurez espiritual en Corinto y Galacia (1 Co 3:1; Gá 4:1-3). Un caso singular aparece en 1 Tesalonicenses 2:7, donde varios manuscritos leen ''nos hicimos tiernos (νήπιοι) entre vosotros,'' evocando la ternura de una madre que amamanta. La extensión metafórica a la inmadurez o la ternura requiere del contexto para manifestarse.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3517', 'spa', 'Nereo, un cristiano saludado por Pablo en Romanos 16', 'Romanos 16:15 incluye saludos a ''Nereo y su hermana, y Olimpas y todos los santos que están con ellos.'' Nereo era un nombre común en el Imperio romano, derivado del dios griego del mar Nereo, padre de las Nereidas. El nombre aparece en inscripciones asociadas con hogares imperiales, sugiriendo que pudo haber sido esclavo o liberto. La mención de la hermana anónima de Nereo insinúa vínculos fraternales estrechos en la comunidad cristiana primitiva. La agrupación de nombres (''todos los santos que están con ellos'') sugiere iglesias domésticas, la estructura organizativa principal del cristianismo del siglo I.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3518', 'spa', 'Neri, antepasado de Jesús mencionado en la genealogía de Lucas', 'Neri aparece en Lucas 3:27 como hijo de Melqui y padre de Salatiel, situándolo en la porción postexílica de la genealogía de Jesús. El nombre es la forma griega del hebreo Nerías (נֵרִיָּה), que significa ''lámpara del SEÑOR'' o ''mi luz es Yahveh''. Nerías es más conocido como padre de Baruc, el escriba de Jeremías (Jeremías 32:12). No es seguro que el Neri genealógico sea idéntico al contemporáneo de Jeremías. Como muchos nombres en la lista postexílica de Lucas, Neri no aparece en ningún otro pasaje bíblico, lo que subraya la oscuridad por la que pasó el linaje davídico durante siglos de dominación extranjera. Sin embargo, los propósitos de Dios discurren tanto por generaciones olvidadas como por reyes célebres.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3519', 'spa', 'isla pequeña o islote', 'Hechos 27:16 relata un momento del tormentoso viaje de Pablo: ''Pasando al abrigo de una pequeña isla (νησίον) llamada Cauda, apenas pudimos asegurar el bote del barco''. La forma diminutiva de νῆσος (''isla'') designa una isla pequeña o islote; en este caso, Cauda (la actual Gavdos), un peñasco rocoso al sur de Creta. El costado protegido de la isla ofreció un respiro momentáneo de la tempestad, permitiendo a los marineros recoger el esquife antes de que se anegara. La atención de Lucas al detalle náutico aporta vivacidad y credibilidad al relato. La pequeña isla se convierte en una discreta nota de gracia dentro de la providencia divina: una protección pasajera que ayuda a preservar la nave y a todos los que iban a bordo hasta el naufragio final en Malta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3520', 'spa', 'Isla; porción de tierra rodeada de agua, usada en Hechos para islas del Mediterráneo y en Apocalipsis para la convulsión escatológica.', 'La palabra griega estándar para isla, que aparece en el Nuevo Testamento principalmente en Hechos durante los viajes mediterráneos de Pablo y en las visiones apocalípticas del Apocalipsis. Lucas nombra islas específicas (Chipre en Hechos 13:6, Malta en Hechos 28:1) como puntos concretos en la expansión geográfica de la iglesia primitiva. En Apocalipsis, las islas se convierten en símbolos de inestabilidad cósmica: ''toda isla huyó'' (Apocalipsis 6:14; 16:20), representando la disolución de la creación ante el juicio de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3521', 'spa', 'Ayuno como disciplina espiritual de abstinencia de alimento; también el Ayuno específico del Día de la Expiación (Yom Kippur)', 'En el Nuevo Testamento, νηστεία designa la práctica de abstenerse voluntariamente de alimento como acto de devoción y abnegación ante Dios. Jesús enseña a sus discípulos que ciertas victorias espirituales solo se obtienen mediante oración y ayuno (Mat 17:21), y la iglesia primitiva ayunaba al designar ancianos (Hch 14:23). Pablo incluye los ayunos entre sus padecimientos apostólicos (2 Cor 6:5; 11:27). En un uso notable, Lucas emplea ''el Ayuno'' como referencia estacional al Día de la Expiación en Hechos 27:9, distinguiéndolo del ayuno genérico mediante el artículo definido y la mayúscula.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3522', 'spa', 'El ayuno en el mundo bíblico nunca fue una simple dieta — era un acto deliberado de abnegación ante Dios. Jesús ayunó cuarenta días en el desierto (Mt', 'El ayuno en el mundo bíblico nunca fue una simple dieta — era un acto deliberado de abnegación ante Dios. Jesús ayunó cuarenta días en el desierto (Mt 4:2) y luego enseñó a sus discípulos cómo ayunar sin ostentación: ''Cuando ayunes, unge tu cabeza y lava tu rostro'' (Mt 6:17). Los fariseos y los discípulos de Juan ayunaban regularmente y cuestionaban por qué los seguidores de Jesús no lo hacían (Mt 9:14-15; Mc 2:18). Los líderes de la iglesia primitiva ayunaban antes de designar ancianos (Hch 13:2-3; 14:23). El verbo νηστεύω denota la abstinencia voluntaria de alimento como disciplina espiritual de devoción, arrepentimiento o duelo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3524', 'spa', 'sobrio, temperante, de mente clara y dominio propio', 'Este adjetivo describe sobriedad y dominio propio, tanto la abstinencia literal del exceso de vino como la claridad mental en sentido figurado. Los obispos deben ser «sobrios» (1 Ti 3:2). Las esposas de los diáconos igualmente deben ser «temperantes» (1 Ti 3:11). Los ancianos deben ser «sobrios» (Tit 2:2). El término enfatiza la lucidez mental, la autodisciplina y la libertad frente a la embriaguez o las pasiones descontroladas. El español «sobrio» conserva bien ese doble sentido de templanza ante el alcohol y moderación en la conducta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3525', 'spa', 'Ser sobrio de mente, tener dominio propio y vigilancia espiritual; mantener lucidez mental', 'Originalmente significaba ''no beber vino'' en el griego clásico, pero este verbo experimentó un cambio metafórico decisivo para la época del NT. Cada aparición neotestamentaria lo emplea en sentido figurado para la sobriedad mental y la vigilancia espiritual, no para la abstinencia literal. Pablo lo vincula con la preparación escatológica: ''seamos sobrios, vistiéndonos con la coraza de la fe'' (1 Tes 5:8), mientras Pedro lo conecta con la oración eficaz (1 Pe 4:7) y la vigilancia contra el diablo. El español ''sed sobrios'' y el alemán ''nüchtern sein'' preservan el doble registro de lucidez física y mental.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3526', 'spa', 'Níger, cognomen latino que significa ''negro'', usado como segundo nombre de Simeón en Hechos 13', 'Hechos 13:1 enumera a los profetas y maestros de la iglesia de Antioquía: ''Bernabé, Simeón llamado Níger, Lucio de Cirene, Manaén y Saulo''. Níger es un sobrenombre latino que significa ''negro'' u ''oscuro'', probablemente alusivo al color de piel o tez morena de Simeón. El nombre sugiere un origen norteafricano o simplemente un apodo descriptivo. El liderazgo de la iglesia de Antioquía era notablemente diverso: Bernabé, levita de Chipre; Lucio de Cirene en Libia; Manaén, vinculado a la corte de Herodes; Saulo, fariseo judío de Tarso; y Simeón con su cognomen romano. Esta asamblea multiétnica y multicultural anticipa el alcance global de la misión a los gentiles que el Espíritu está a punto de lanzar al separar a Bernabé y Saulo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3527', 'spa', 'Nicanor, uno de los siete varones elegidos para servir a la iglesia de Jerusalén en Hechos 6', 'Hechos 6:5 menciona a Nicanor entre los siete judíos helenistas designados para supervisar la distribución diaria de alimentos a las viudas en la iglesia de Jerusalén. El nombre, que significa ''vencedor'' o ''victorioso'', era frecuente en el mundo helenístico. Aunque llamados a administrar una labor práctica de caridad, los siete debían estar ''llenos del Espíritu y de sabiduría'', requisitos que difuminan la frontera entre servicio social y liderazgo espiritual. La tradición a veces los denomina los primeros diáconos, aunque Hechos no emplea ese término. Nicanor desaparece del registro bíblico tras su nombramiento, pero su elección atestigua el compromiso de la iglesia primitiva con la unidad a través de las divisiones culturales y su reconocimiento de que servir las mesas no es un ministerio menor que predicar la Palabra.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3528', 'spa', 'Vencer, conquistar, ser victorioso; prevalecer sobre adversarios, el mal u oposición espiritual; en voz pasiva, ser derrotado', 'Vencer, conquistar, ser victorioso; prevalecer sobre adversarios, el mal u oposición espiritual; en voz pasiva, ser derrotado');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3529', 'spa', 'victoria, conquista o triunfo; la superación de un enemigo u obstáculo', 'Primera Juan 5:4 declara: ''Esta es la victoria (νίκη) que ha vencido al mundo: nuestra fe''. El término denota triunfo en batalla, éxito en competiciones atléticas o victoria en contiendas legales. La literatura clásica personifica a Niké como la diosa alada de la victoria, compañera de Atenea y Zeus. El uso joánico es teológico: la fe misma es el poder conquistador que derrota la oposición, la tentación y las mentiras del mundo. La victoria es a la vez ya consumada (por la resurrección y exaltación de Cristo) y continuamente apropiada por los creyentes mediante la confianza en el Hijo de Dios. Lo que parece debilidad — la fe en un Mesías crucificado — resulta ser el triunfo definitivo sobre todo poder hostil.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3530', 'spa', 'Nicodemo; fariseo y miembro del Sanedrín que vino a Jesús de noche (Juan 3)', 'Nombre propio que identifica a Nicodemo, fariseo prominente y miembro del Sanedrín que aparece exclusivamente en el Evangelio de Juan. Se acerca a Jesús en secreto, de noche, con preguntas teológicas genuinas (Jn 3:1-9); luego defiende el debido proceso ante el concilio (Jn 7:50); y finalmente asiste a José de Arimatea en la sepultura de Jesús con una cantidad generosa de especias (Jn 19:39). El nombre significa ''victoria del pueblo'' (del griego νίκη + δῆμος). Las traducciones europeas conservan la forma griega de modo cercano: en español ''Nicodemo'', en francés ''Nicodème'', en alemán ''Nikodemus''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3532', 'spa', 'Nicolás, uno de los siete hombres elegidos para servir a la iglesia de Jerusalén, identificado como prosélito de Antioquía', 'Hechos 6:5 menciona a Nicolás en último lugar entre los siete, añadiendo que era «prosélito de Antioquía», un gentil convertido al judaísmo que luego abrazó la fe cristiana. Su nombre griego (que significa «vencedor del pueblo») y su origen en Antioquía, centro de cultura helenística, lo señalan como figura puente entre el mundo judío y el gentil. Algunos padres de la iglesia, sin evidencia sólida, lo vincularon con los nicolaítas condenados en Apocalipsis 2:6, 15, conexión probablemente espuria. Su verdadera importancia radica en que incluso un prosélito gentil podía servir como líder en la iglesia de Jerusalén.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3533', 'spa', 'Nicópolis, ciudad fundada por Augusto; probablemente la de Epiro donde Pablo planeaba pasar el invierno', 'Pablo instruye a Tito en Tito 3:12: «Haz todo lo posible por venir a Nicópolis, porque he decidido pasar allí el invierno». Varias ciudades llevaban el nombre Nicópolis («ciudad de la victoria»), conmemorando triunfos militares; solo Augusto fundó varias. La candidata más probable es Nicópolis de Epiro (noroeste de Grecia), construida para celebrar la victoria de Augusto en Accio en el 31 a. C. Ubicada en la costa del Adriático, era un refugio invernal lógico para los viajes mediterráneos y una base estratégica para el ministerio en Grecia y el imperio occidental. La estancia planeada de Pablo sugiere actividad misionera continua incluso en sus últimos años. Si llegó a Nicópolis antes de su arresto final y martirio sigue siendo incierto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3534', 'spa', 'Victoria; triunfo decisivo, especialmente sobre la muerte y el sepulcro', 'Forma griega tardía de νίκη (victoria), empleada en el Nuevo Testamento casi exclusivamente en el contexto del triunfo definitivo de Dios. Mateo 12:20 cita la promesa de Isaías de que la justicia será llevada ''hasta la victoria'', mientras que el denso pasaje de 1 Corintios 15:54-57 celebra la absorción escatológica de la muerte en la victoria. La exclamación exultante de Pablo ''¿Dónde está, oh muerte, tu victoria?'' transforma un desafío veterotestamentario en un himno de resurrección. El término designa siempre un triunfo completo y definitivo, nunca una victoria parcial.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3535', 'spa', 'Nínive, capital de la antigua Asiria (hebreo נִינְוֵה; nombre propio)', 'La gran capital asiria a orillas del río Tigris, destruida en el 612 a. C. pero que pervive en la memoria bíblica como sinónimo tanto de maldad como de misericordia divina. Jesús hace referencia al arrepentimiento de Nínive ante la predicación de Jonás en Lucas 11:32 (Texto Recibido). Sus imponentes murallas y su sofisticación cultural la convirtieron en una ciudad legendaria en todo el antiguo Cercano Oriente. Las excavaciones arqueológicas han confirmado su grandeza, incluida la extensa biblioteca de Asurbanipal hallada allí.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3536', 'spa', 'ninivitas, habitantes de la antigua ciudad asiria de Nínive', 'Los ninivitas eran los habitantes de Nínive, la gran capital asiria a la que fue enviado Jonás. Jesús los emplea como ejemplo positivo: se arrepintieron ante la predicación de Jonás y se levantarán en el juicio contra la generación de Jesús, que rechazó a uno mayor que Jonás (Mt 12:41; Lc 11:30, 32). El contraste es contundente: los ninivitas paganos atendieron la advertencia, mientras que el Israel del pacto rechazó al Mesías. Su arrepentimiento ejemplar sirve como reproche profético.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3537', 'spa', 'palangana o recipiente para lavar, usado para el lavamiento de pies o la purificación ritual', 'Juan 13:5 registra el acto de humildad de Jesús: «Echó agua en una palangana (νιπτῆρα) y comenzó a lavar los pies de sus discípulos, secándolos con la toalla». El término designa un recipiente grande usado específicamente para lavarse. En el antiguo Oriente Próximo, lavar los pies era tarea servil de siervos para huéspedes que viajaban por caminos polvorientos. Jesús, maestro y Señor, asume el papel del esclavo más humilde, en parábola vivida de su misión. La palangana se convierte en símbolo de servicio y amor abnegado. La negativa de Pedro revela su incapacidad para comprender el simbolismo: Jesús limpia no solo pies sino almas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3538', 'spa', 'Derivado de la forma más antigua νίζω, este verbo denota específicamente lavar una parte del cuerpo, a diferencia de bañar a la persona entera. En los', 'Derivado de la forma más antigua νίζω, este verbo denota específicamente lavar una parte del cuerpo, a diferencia de bañar a la persona entera. En los Evangelios aparece en contextos de lavado ritual de manos antes de las comidas (Mt 15:2; Mc 7:3), de Jesús lavando los pies de los discípulos como acto de amor servicial (Jn 13:5-14), y del mandato al ciego de lavarse en el estanque de Siloé (Jn 9:7, 11). El griego distingue consistentemente este lavado parcial de λούω, que significa bañar el cuerpo entero. El español ''lavar'' preserva bien el sentido físico directo del verbo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3539', 'spa', 'Entender, percibir, considerar: captar algo mediante la reflexión mental en lugar de la experiencia sensorial. Derivado de νοῦς (mente), νοέω describe', 'Entender, percibir, considerar: captar algo mediante la reflexión mental en lugar de la experiencia sensorial. Derivado de νοῦς (mente), νοέω describe el acto de percibir con el intelecto, una comprensión que va más allá de la mera observación hacia un entendimiento genuinamente intelectual y espiritual. Jesús lo emplea repetidamente con frustración cuando los discípulos no logran captar el significado de los milagros de los panes: ''¿Aún no entendéis?'' (Mt 16:9, 11; Mr 8:17). El discurso apocalíptico en Mateo 24:15 y Marcos 13:14 inserta el paréntesis ''el que lee, entienda'' (ὁ ἀναγινώσκων νοείτω), invitando a un desciframiento más profundo de la profecía de Daniel. Pablo lo usa en Romanos 1:20 para argumentar que los atributos invisibles de Dios son νοούμενα —percibidos mentalmente— a través de la creación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3540', 'spa', 'La mente o los pensamientos como sede de percepción y reflexión; también ardid o maquinación astuta, especialmente de Satanás', 'Νόημα capta la vida interior de la mente: lo que una persona piensa, percibe y se propone. Pablo lo usa con mayor frecuencia en 2 Corintios, donde abarca desde las mentes endurecidas de Israel que no pueden percibir la gloria del nuevo pacto (2 Cor 3:14) hasta todo pensamiento llevado cautivo a Cristo (2 Cor 10:5). El pasaje de Filipenses promete que la paz de Dios guardará los corazones y los νοήματα de los creyentes (Fil 4:7). Sin embargo, en 2 Cor 2:11 la misma palabra toma un giro sombrío, refiriéndose a las maquinaciones calculadas de Satanás, un recordatorio de que la actividad mental puede dirigirse tanto hacia la manipulación astuta como hacia la adoración.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3541', 'spa', 'ilegítimo, nacido fuera del matrimonio; bastardo o espurio', 'Hebreos 12:8 emplea la metáfora de la disciplina divina: «Si no recibís disciplina —y todos la reciben— entonces sois hijos ilegítimos (νόθοι) y no verdaderos hijos». El término designa a hijos nacidos fuera del matrimonio legal, que carecían de derechos de herencia y del pleno reconocimiento paterno. En el uso clásico, la palabra se extiende a todo lo falsificado o espurio. El argumento del autor es contundente: la corrección de Dios demuestra la filiación. Quienes escapan de la disciplina no gozan de privilegio, sino de exclusión. Los herederos legítimos reciben formación y preparación para su herencia. Ser bastardo equivale a carecer de relación con Dios, destino más grave que soportar dificultades temporales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3543', 'spa', 'Pensar, suponer o asumir; en voz pasiva, ser comúnmente considerado o tenido por algo. Derivado de νόμος (''costumbre, ley''), νομίζω conlleva un matiz ', 'Pensar, suponer o asumir; en voz pasiva, ser comúnmente considerado o tenido por algo. Derivado de νόμος (''costumbre, ley''), νομίζω conlleva un matiz de pensamiento convencional o esperado: lo que uno habitualmente supone o da por sentado. Jesús lo usa de manera incisiva en Mt 5:17 y 10:34: ''No penséis que he venido para...'', corrigiendo suposiciones populares erróneas. Lucas lo emplea para la suposición natural pero incorrecta de los padres de Jesús de que él estaba en la caravana (Lc 2:44). La única aparición pasiva en Lucas 3:23, ''se pensaba que era hijo de José'', tiene una carga teológica profunda, distinguiendo sutilmente la opinión pública de la realidad divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3544', 'spa', 'Relativo a la ley; como sustantivo, experto en la Ley mosaica, jurista o erudito legal en la tradición religiosa judía.', 'En el Nuevo Testamento, este adjetivo aparece con mayor frecuencia como sustantivo, refiriéndose a alguien versado en la Torá y su interpretación rabínica: un erudito legal profesional. Los Evangelios Sinópticos los presentan poniendo a prueba a Jesús o resistiéndose a su mensaje (Lucas 7:30; 10:25). En su único uso puramente adjetival (Tito 3:9), describe contiendas como ''legales'', es decir, relativas a cuestiones de la ley y no a una persona. El término abarca tanto la función profesional del intérprete de la Torá como la cualidad descriptiva de lo perteneciente al ámbito jurídico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3546', 'spa', 'moneda, especialmente pieza de curso legal acuñada por autoridad oficial; dinero en forma acuñada', 'Cuando los fariseos intentan atrapar a Jesús con una pregunta sobre impuestos (Mateo 22:15-22), él pide que le muestren la moneda del tributo (νόμισμα). Le presentan un denario con la imagen de César. La célebre respuesta —«Dad al César lo que es del César, y a Dios lo que es de Dios»— transforma la trampa en enseñanza. El término νόμισμα enfatiza el carácter legal de la moneda: dinero autorizado por costumbre o ley. La raíz (νόμος, «ley») apunta al contrato social que otorga valor a la moneda. Al poseer la moneda de César, los fariseos aceptan tácitamente la autoridad romana, y Jesús afirma una lealtad superior: César reclama impuestos, pero Dios reclama a la persona entera.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3547', 'spa', 'maestro de la ley, experto en la legislación mosaica y la Torá', 'Un maestro de la ley es un experto en la Torá, alguien formado para interpretar y enseñar la legislación mosaica. Lucas los menciona entre los presentes cuando Jesús sanó al paralítico (Lc 5:17). Gamaliel es identificado como «maestro de la ley, honrado por todo el pueblo» (Hch 5:34). Pablo advierte contra quienes desean ser «maestros de la ley» sin entender lo que afirman (1 Ti 1:7). El término designa una pericia profesional de carácter jurídico-teológico dentro del judaísmo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3548', 'spa', 'legislación, promulgación de la ley; el acto o proceso de establecer un código legal', 'Pablo enumera los privilegios del pacto de Israel en Romanos 9:4: de ellos son «la adopción, la gloria, los pactos, la promulgación de la ley (νομοθεσία), el culto y las promesas». El término designa el acto de legislar o el cuerpo legislativo en sí, en este contexto, la ley mosaica entregada en el Sinaí. En el griego clásico se empleaba para referirse al proceso legislativo o a un código de leyes promulgado por un estado. Para Pablo, la ley es una de varias señales de la relación especial de Israel con Dios, aunque ha sido cumplida y trascendida en Cristo. La tragedia que Pablo lamenta es que Israel, a quien le fue dada la ley, tropezó con la piedra angular (Cristo) en su celo por una justicia basada en la ley.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3550', 'spa', 'legislador; quien establece o promulga leyes', 'Santiago 4:12 plantea una pregunta retórica: «Uno solo es el legislador (νομοθέτης) y juez, el que puede salvar y destruir. Pero tú, ¿quién eres para juzgar a tu prójimo?» El término designa a alguien con autoridad para establecer leyes. En la Atenas clásica, los νομοθέται eran comisiones encargadas de revisar o crear legislación. El argumento de Santiago es teológico: solo Dios tiene derecho a legislar, porque solo él tiene el poder de ejecutar sus veredictos: salvar o destruir. El juicio humano entre creyentes usurpa la prerrogativa divina. Cuando los creyentes difaman o condenan a otros, actúan como si fueran legisladores en lugar de súbditos bajo un solo Rey.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3551', 'spa', 'Ley, ordenanza; especialmente la Torá mosaica, pero también la ley como principio o sistema', 'Νόμος es una de las palabras con mayor peso teológico del Nuevo Testamento. Derivada del verbo νέμω (''distribuir, administrar''), originalmente significaba ''costumbre'' o ''convención'' en el griego clásico, pero en la Septuaginta y el Nuevo Testamento se refiere de forma abrumadora a la Torá — la Ley de Moisés. Las cartas de Pablo exploran su función, sus limitaciones y su relación con la gracia con extraordinaria profundidad (Ro 3:21; 7:7-12; Gá 3:24). Con y sin artículo, νόμος puede designar el Pentateuco específicamente, todo el Antiguo Testamento o la ley como principio abstracto. Español ley lo traduce de manera uniforme.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3552', 'spa', 'estar enfermo, padecer dolencia; sufrir una enfermedad o malestar físico o mental', 'Pablo reprende a ciertos maestros en 1 Timoteo 6:4 como personas «envanecidas, que nada entienden, y que tienen un afán enfermizo (νοσῶν) por controversias y disputas de palabras». El verbo significa literalmente «estar enfermo» o «padecer una dolencia». El uso clásico lo aplica a enfermedades corporales, trastornos mentales e incluso a la enfermedad de una ciudad durante una plaga. Pablo extiende la metáfora médica para describir una fascinación obsesiva y patológica con debates y disputas. Los falsos maestros no simplemente yerran; están enfermos en su manera de pensar. Su afán por la discusión no es rigor intelectual sino enfermedad espiritual, una compulsión que produce envidia, contienda y división en lugar de piedad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3553', 'spa', 'enfermedad, dolencia o padecimiento; condición patológica del cuerpo o de la mente', 'Juan 5:4 (en algunos manuscritos) describe a un ángel que agitaba las aguas del estanque de Betesda: «el primero que descendía al estanque después del movimiento del agua quedaba sano de cualquier enfermedad (νοσήματος) que tuviera». El término designa una enfermedad o dolencia en general, ya sea física o mental. El griego clásico extiende la metáfora a males sociales: desorden político, vicio moral o la enfermedad de un estado. Aunque la base textual del versículo es disputada (está ausente en los manuscritos más antiguos), el lenguaje refleja la creencia popular sobre las propiedades curativas del estanque. La historia prepara el escenario para la sanidad autoritativa de Jesús: él no necesita aguas mágicas ni intervención angélica. Su sola palabra trae plenitud.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3554', 'spa', 'El sustantivo νόσος (nosos) denota enfermedad o dolencia grave en sentido general, y aparece casi exclusivamente en los resúmenes de los Evangelios Si', 'El sustantivo νόσος (nosos) denota enfermedad o dolencia grave en sentido general, y aparece casi exclusivamente en los resúmenes de los Evangelios Sinópticos sobre la actividad sanadora de Jesús. La fórmula repetida de Mateo —Jesús recorría todo lugar ''sanando toda enfermedad y toda dolencia'' (Mt 4:23; 9:35; 10:1)— empareja νόσος con μαλακία (debilidad) para abarcar todo el espectro del sufrimiento físico. Mr 1:34 y Lc 4:40; 6:17; 7:21; 9:1 emplean la palabra de manera similar en pasajes de resumen. Su virtual ausencia en Juan y las Epístolas subraya su función como marcador narrativo sinóptico de la irrupción del reino en el ámbito de la enfermedad. El español ''enfermedad'' y el francés ''maladie'' traducen directamente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3555', 'spa', 'nidada o cría de aves; grupo de polluelos cuidados por su madre', 'Jesús se lamenta sobre Jerusalén en Lucas 13:34: «¡Cuántas veces quise reunir a tus hijos, como la gallina reúne a su nidada (νοσσιάν) bajo sus alas, pero no quisiste!» La imagen es tierna y doméstica: una gallina madre que protege a sus polluelos del peligro cobijándolos bajo sus alas. El término designa la cría o nidada de aves como grupo. Jesús se sitúa en el rol maternal, ofreciendo protección, calor y seguridad a un Israel vulnerable. La tragedia radica en su rechazo. A pesar de repetidos llamados proféticos y ahora la presencia misma del Mesías, Jerusalén rechaza el refugio ofrecido. El instinto protector de la gallina no encuentra correspondencia de confianza en los polluelos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3556', 'spa', 'polluelos o crías de ave; las crías de aves que aún están bajo el cuidado de sus padres', 'En Mateo 23:37, Jesús exclama: «¡Cuántas veces quise reunir a tus hijos, como la gallina reúne a sus polluelos (νοσσία) bajo sus alas, y no quisiste!». El término designa a las crías de aves, indefensas y dependientes. La imagen evoca tanto la vulnerabilidad de los polluelos como el instinto protector de la gallina. Jesús se presenta no como un guerrero conquistador, sino con ternura maternal, una llamativa imagen femenina aplicada al Mesías. El rechazo de Jerusalén a este amparo sella su destino, dejando la ciudad expuesta a la destrucción.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3557', 'spa', 'sustraer, quedarse con lo ajeno, hurtar, apropiarse indebidamente', 'Apropiarse indebidamente o retener de forma deshonesta lo que pertenece a otro. Ananías y Safira «sustrajeron» parte del precio de venta fingiendo entregar la totalidad (Hch 5:2-3). Pablo advierte a los esclavos que no cometan hurtos contra sus amos (Tit 2:10). El término implica una retención engañosa o un robo menor con ocultamiento. El griego νοσφίζω significa separar para uno mismo aquello que debería ir a otro, combinando la acción de tomar con la intención de encubrir.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3558', 'spa', 'El viento del sur o el sur como punto cardinal; usado para clima, geografía y la reunión escatológica desde todos los puntos cardinales', 'Νότος cumple una doble función en el NT como término meteorológico (el viento del sur) y como marcador geográfico (el sur como dirección cardinal). Cuando Jesús dice que la reina del Sur se levantará en el juicio (Mat 12:42, Luc 11:31), νότος señala una región (Sabá, en el sur de Arabia). Cuando describe la predicción del tiempo, un viento del sur significa calor abrasador (Luc 12:55). En Lucas 13:29 vendrán personas del este, oeste, norte y del νότος para sentarse a la mesa en el reino de Dios. Hechos 27:13 registra un suave viento del sur en el Mediterráneo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3559', 'spa', 'amonestación, advertencia, instrucción correctiva', 'La amonestación es una instrucción correctiva, una advertencia destinada a reconducir a alguien hacia el pensamiento o la conducta rectos. Pablo señala que los ejemplos del Antiguo Testamento fueron escritos «para amonestación nuestra» (1 Co 10:11). Instruye a los padres a criar a sus hijos «en la disciplina e instrucción del Señor» (Ef 6:4). Después de dos amonestaciones, se debe rechazar a la persona divisiva (Tit 3:10). El griego νουθεσία combina νοῦς (mente) y τίθημι (poner), es decir, «poner algo en la mente»: corregir mediante la palabra.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3560', 'spa', 'Amonestar, advertir o instruir con intención correctiva; literalmente, poner algo en la mente para redirigir la conducta.', 'Νουθετέω combina νοῦς (mente) y τίθημι (poner): significa literalmente colocar algo en la mente de alguien. A diferencia de la reprensión severa, mezcla advertencia con enseñanza, buscando la corrección y no la condenación. Pablo lo emplea para describir su propia práctica pastoral: amonestando a los ancianos de Éfeso noche y día durante tres años (Hch 20:31), exhortando a los corintios como hijos amados (1 Co 4:14), y describiendo la responsabilidad mutua de los creyentes de amonestarse unos a otros (Col 3:16, Ro 15:14). El español «amonestar» conserva perfectamente ese tono correctivo pero afectuoso.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3561', 'spa', 'luna nueva, primer día del mes lunar; fiesta u observancia asociada con la luna nueva', 'Pablo advierte en Colosenses 2:16 que nadie juzgue a los creyentes «en cuanto a días de fiesta, luna nueva (νουμηνίας) o sábados». El término designa el primer día del mes lunar, cuando reaparece la luna creciente. En el calendario de Israel, las lunas nuevas se marcaban con sacrificios y toques de trompeta (Números 10:10; 28:11-15). Pablo advierte que estas regulaciones calendáricas ya no son obligatorias bajo el nuevo pacto. Eran sombras que apuntaban a Cristo; ahora que ha llegado la realidad, las sombras pierden su fuerza.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3562', 'spa', 'sabiamente, con prudencia o entendimiento; de manera sensata y perspicaz', 'Cuando un escriba responde sabiamente sobre el mandamiento más importante, Jesús le dice en Marcos 12:34: «No estás lejos del reino de Dios, porque respondiste sabiamente (νουνεχῶς)». El adverbio deriva de νοῦς (''mente'') y ἔχω (''tener''), significando ''con entendimiento''. La sabiduría del escriba radica en captar la prioridad del amor a Dios y al prójimo por encima de la observancia ritual. La aprobación de Jesús es significativa: quien comprende la verdadera intención de la ley se halla más cerca del reino. Sin embargo, la cercanía no es llegada: el paso final exige seguir a Jesús mismo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3563', 'spa', 'Mente, intelecto; la facultad de percepción, pensamiento, razonamiento moral y comprensión espiritual.', 'Mente, intelecto; la facultad de percepción, pensamiento, razonamiento moral y comprensión espiritual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3564', 'spa', 'Ninfa o Ninfas, cristiano/a en cuya casa se reunía una iglesia, saludado/a por Pablo', 'Pablo cierra Colosenses 4:15 con saludos: «Saluden a los hermanos en Laodicea, y a Ninfa (Νύμφαν) y a la iglesia que se reúne en su casa». La ambigüedad del acusativo griego deja incierto si se trata de Ninfa (femenino) o Ninfas (masculino). La mayoría de las traducciones modernas prefieren el femenino, representando a una mujer que albergaba una iglesia doméstica en Laodicea. Ninfa se suma así a otras líderes como Febe, Priscila y Lidia. Las iglesias domésticas eran la norma antes de Constantino; abrir el propio hogar era infraestructura esencial para la difusión del evangelio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3565', 'spa', 'Novia; nuera — una mujer joven en relación con su matrimonio o con la familia de su esposo.', 'El sustantivo νύμφη posee dos significados estrechamente relacionados pero distinguibles en el Nuevo Testamento, ambos enraizados en la relación matrimonial. Como «novia», aparece en algunas de las imágenes más vívidas de la Escritura: el amigo del novio se goza al oír la voz de la novia (Jn 3:29), y la ciudad santa desciende «preparada como una novia ataviada para su esposo» (Ap 21:2). Como «nuera», aparece en la advertencia de Jesús de que vino a poner «a la nuera contra su suegra» (Mt 10:35, Lc 12:53), un término de parentesco que describe la relación de la mujer con la madre de su esposo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3566', 'spa', 'Νυμφίος designa al hombre que se casa, la figura masculina central en la celebración nupcial. Jesús recurre a esta imagen cuando explica por qué sus d', 'Νυμφίος designa al hombre que se casa, la figura masculina central en la celebración nupcial. Jesús recurre a esta imagen cuando explica por qué sus discípulos no ayunan: los invitados a la boda no pueden estar de luto mientras el novio está con ellos (Mt 9:15; Mc 2:19-20). La Parábola de las Diez Vírgenes gira en torno a la llegada tardía del novio a medianoche (Mt 25:1-10), y Juan el Bautista se identifica gozosamente como el amigo del novio (Jn 3:29). La imagen se carga de significado cristológico: Jesús es el novio mesiánico de su pueblo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3567', 'spa', 'cámara nupcial, salón de bodas, el recinto o el séquito asociado al novio', 'La cámara nupcial se refiere al contexto de la celebración de bodas, en particular al séquito del novio o al banquete mismo. Jesús pregunta: «¿Acaso pueden los invitados a la boda estar de luto mientras el novio está con ellos?» (Mt 9:15; Mr 2:19; Lc 5:34). La expresión «hijos de la cámara nupcial» es un semitismo que designa a los invitados o acompañantes de la boda. El griego νυμφών puede referirse tanto al recinto físico como al ambiente festivo de la celebración.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3568', 'spa', 'Ahora — adverbio de tiempo presente que marca el momento actual, la era presente o una transición lógica en el argumento', 'Νῦν es el adverbio temporal griego estándar para ''ahora'', pero en el Nuevo Testamento a menudo conlleva más que mera cronología. Puede señalar el presente decisivo de la historia de la salvación — ''ahora es el día de salvación'' (2 Co 6:2) — o el contraste entre un estado anterior y la nueva realidad en Cristo: ''en otro tiempo erais tinieblas, mas ahora sois luz'' (Ef 5:8). Pablo lo emplea con frecuencia como marcador discursivo que da giro a su argumento. Español ahora capta la inmediatez del momento presente que este adverbio transmite a lo largo de sus 147 apariciones.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3569', 'spa', 'ahora (adverbio de tiempo presente, pasado inmediato o futuro inminente); el momento o la era actual', 'El adverbio νῦν abarca el significado de «ahora» en todo un espectro de cercanía temporal: el momento presente, la época actual («los mortales de nuestro tiempo», «la costumbre vigente»), el pasado inmediato («pero ahora Menelao ha vencido») o el futuro inminente («enseguida probaré con mi lanza»). Expresiones como οἱ νῦν ἄνθρωποι significan «la gente del presente». Esta palabra ancla el discurso en la ubicación temporal del hablante, contrastando con el pasado o el futuro y subrayando la urgencia o relevancia de la situación actual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3570', 'spa', 'Forma intensificada de la palabra griega común para ''ahora,'' este adverbio traza una línea nítida entre un estado anterior y la realidad presente. Pab', 'Forma intensificada de la palabra griega común para ''ahora,'' este adverbio traza una línea nítida entre un estado anterior y la realidad presente. Pablo lo emplea con fuerza retórica: ''Pero ahora, aparte de la ley, se ha manifestado la justicia de Dios'' (Ro 3:21); ''Pero ahora que habéis sido libertados del pecado'' (Ro 6:22). La construcción ''pero ahora'' no es meramente temporal — está cargada teológicamente, marcando el punto de inflexión que introduce el evangelio. Νυνί señala el contraste decisivo entre el ''antes'' y el ''ahora'' de la obra redentora de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3571', 'spa', 'νύξ — noche; período de oscuridad desde el ocaso hasta el amanecer, también usado figuradamente para la oscuridad moral', 'El sustantivo femenino νύξ («noche») designa el período de oscuridad entre el ocaso y el amanecer, y aparece 62 veces en el Nuevo Testamento. Posee peso tanto literal como teológico. En sentido literal marca el escenario temporal de sucesos clave: la huida a Egipto (Mt 2:14), Jesús caminando sobre el agua en la cuarta vigilia (Mt 14:25), la fuga de Pablo en Damasco (Hch 9:25) y la tormenta de catorce noches (Hch 27:27). En sentido figurado, la noche representa la oscuridad espiritual opuesta a la luz de Cristo (Ro 13:12; 1 Ts 5:5-7).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3574', 'spa', 'Período de veinticuatro horas que abarca noche y día; un ciclo completo de día y noche', 'Este término griego designa un ciclo completo de día y noche, es decir, un período de veinticuatro horas. Pablo lo emplea en 2 Corintios 11:25 al relatar sus penurias: pasó «una noche y un día» a la deriva en el mar. La naturaleza compuesta de la palabra (que combina ''noche'' y ''día'') subraya la totalidad del período, marcando la duración completa de su peligro. Los traductores de diversas lenguas conservan esta estructura compuesta (español ''un día y una noche'', francés ''jour et nuit''), destacando el lapso temporal preciso en vez de un vago ''mucho tiempo''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3575', 'spa', 'Noé, el patriarca justo que construyó el arca y sobrevivió al gran diluvio; figura clave de fe y juicio divino.', 'El nombre propio indeclinable Νῶε (del hebreo נֹחַ, que significa «descanso» o «consuelo») aparece ocho veces en el Nuevo Testamento, siempre en referencia al patriarca del relato del diluvio. Jesús cita los días de Noé como paradigma de la llegada inesperada del Hijo del Hombre (Mt 24:37-38, Lc 17:26-27). El autor de Hebreos presenta a Noé como modelo de fe que actuó ante la advertencia divina (He 11:7), mientras que Pedro lo llama «pregonero de justicia» y usa el arca como tipo de la salvación bautismal (1 P 3:20, 2 P 2:5).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3577', 'spa', 'La espalda del cuerpo humano o animal; la superficie dorsal desde los hombros hasta la parte baja de la columna vertebral', 'En la literatura griega, esta palabra designa la espalda de personas o animales, especialmente la columna vertebral y la musculatura circundante. Pablo cita el Salmo 69:23 en Romanos 11:10, empleando lenguaje de juicio: ''encorva sus espaldas para siempre''. La imagen evoca una carga aplastante o un encorvamiento perpetuo, una postura de derrota. Aunque el término aparece en Homero describiendo guerreros y animales, su único uso en el Nuevo Testamento proviene de la tradición metafórica de la Septuaginta, donde una espalda encorvada simboliza opresión o juicio divino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3579', 'spa', 'Hospedar o recibir como huésped; sorprenderse o considerar algo extraño; presentar algo desconocido o ajeno. Derivado de ξένος (extranjero, forastero)', 'Hospedar o recibir como huésped; sorprenderse o considerar algo extraño; presentar algo desconocido o ajeno. Derivado de ξένος (extranjero, forastero), este verbo une dos facetas del encuentro con lo desconocido: acoger a un forastero en tu hogar y sentir extrañeza ante algo ajeno. Su uso principal en el NT es el alojamiento hospitalario: Pedro hospedándose con Simón el curtidor (Hch 10:6), Mnasón alojando a Pablo (Hch 21:16) y el hospedaje de ángeles sin saberlo (Heb 13:2). Pero Pedro también lo emplea para la sorpresa que los incrédulos sienten ante la vida transformada de los cristianos (1 Pe 4:4, 12). En Atenas, el verbo toma un giro adjetival cuando acusan a Pablo de introducir ''cosas extrañas'' (Hch 17:20).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3580', 'spa', 'Recibir y cuidar a extranjeros o huéspedes; practicar la hospitalidad hacia quienes están fuera del propio hogar', 'Este verbo describe la práctica activa de acoger a extraños en el propio hogar, brindándoles comida y refugio. En 1 Timoteo 5:10, aparece entre los requisitos para que las viudas sean inscritas en el sostenimiento de la iglesia: debía haber ''practicado la hospitalidad''. El contexto cultural es fundamental: la hospitalidad antigua implicaba riesgo y sacrificio, no mera cortesía. Las traducciones multilingües capturan la naturaleza tangible y costosa de esta virtud, que fue pilar de la vida comunitaria cristiana primitiva.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3581', 'spa', 'Extranjero, forastero, desconocido; extraño o desconocido (adjetival); anfitrión, quien recibe a los extranjeros. ξένος es una palabra construida sobr', 'Extranjero, forastero, desconocido; extraño o desconocido (adjetival); anfitrión, quien recibe a los extranjeros. ξένος es una palabra construida sobre la reciprocidad. En el griego clásico designaba tanto al huésped como al anfitrión: dos partes unidas por la obligación sagrada de la ξενία, la hospitalidad hacia los extranjeros. El Nuevo Testamento conserva esta notable bidireccionalidad. En Mateo 25:35-44, acoger al ''extranjero'' (ξένος) es el criterio por el cual las naciones son juzgadas. Cuando Pablo llama a Gayo ''hospedador'' (ξένος) de toda la iglesia en Ro 16:23, la palabra gira hacia el polo opuesto: el que recibe en vez del recibido. Un tercer uso puramente adjetival aparece en He 13:9 (''doctrinas extrañas'') y 1 P 4:12 (''la prueba de fuego como si fuera cosa extraña''), donde ξένος modifica sustantivos abstractos con el sentido de ''desconocido'' o ''ajeno a lo esperado''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3583', 'spa', 'Marchitarse, secarse o desecarse; en la voz activa, hacer que algo se seque o se agoste. Un verbo físico vívido, ξηραίνω pinta imágenes de vegetación ', 'Marchitarse, secarse o desecarse; en la voz activa, hacer que algo se seque o se agoste. Un verbo físico vívido, ξηραίνω pinta imágenes de vegetación abrasada y miembros atrofiados a lo largo del Nuevo Testamento. La higuera maldecida que se secó de la noche a la mañana (Mt 21:19-20; Mr 11:20-21) se convirtió en una parábola actuada de juicio, mientras que la semilla en terreno pedregoso que se secó por falta de raíz (Mt 13:6; Mr 4:6; Lc 8:6) ilustra la fe superficial. La palabra también describe la mano seca de un hombre (Mr 3:1) y el secamiento apocalíptico del Éufrates (Ap 16:12).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3584', 'spa', 'Seco, reseco, marchito — de una parte del cuerpo paralizada o atrofiada, o de tierra firme en contraste con el mar.', 'El adjetivo ξηρός («seco») aparece ocho veces en el Nuevo Testamento con dos sentidos reconocibles. Con mayor frecuencia describe un miembro marchito o paralizado: el hombre de la «mano seca» en los relatos sinópticos de sanidad (Mt 12:10, Mr 3:3, Lc 6:6-8) y los enfermos junto al estanque de Betesda (Jn 5:3). En su otro sentido describe tierra seca o material seco: los israelitas cruzaron el Mar Rojo «por tierra seca» (He 11:29), y Jesús contrasta lo que se hace «en el leño verde» con lo que sucederá «en el seco» (Lc 23:31). También lo usa para quienes recorren «mar y tierra» para hacer un prosélito (Mt 23:15).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3586', 'spa', 'En el Nuevo Testamento, esta palabra abarca todo el ciclo vital de la madera — desde el árbol vivo hasta la cruz en la que Cristo fue colgado. Lucas c', 'En el Nuevo Testamento, esta palabra abarca todo el ciclo vital de la madera — desde el árbol vivo hasta la cruz en la que Cristo fue colgado. Lucas conserva un proverbio sobre la leña verde y la seca (Lc 23:31), mientras Pablo la enumera entre los materiales de construcción perecederos (1 Co 3:12). De manera más notable, la predicación apostólica llama repetidamente a la cruz un ''madero'' (Hch 5:30; 10:39; 13:29; Gá 3:13; 1 P 2:24), evocando deliberadamente la fórmula de maldición del Deuteronomio. En las escenas sinópticas del arresto, la misma palabra designa los palos que portaba la turba. El español distingue con precisión ''árbol,'' ''palos,'' ''madera'' y ''cepo.''');